using System.Diagnostics.CodeAnalysis;

namespace Ladder.DI;

/// <summary>
/// Exception messages. The wording is Microsoft's (<c>Microsoft.Extensions.DependencyInjection/src/Resources/Strings.resx</c>)
/// because callers and tests match on it, and the exception types are part of the contract.
/// </summary>
internal static class Errors
{
    public static InvalidOperationException CircularDependency(string path) => new(path);

    public static InvalidOperationException NoConstructorMatch(Type implementation) =>
        new($"A suitable constructor for type '{implementation}' could not be located. Ensure the type is concrete and services are registered for all parameters of a public constructor.");

    public static InvalidOperationException UnableToActivate(Type implementation) =>
        new($"No constructor for type '{implementation}' can be instantiated using services from the service container and default values.");

    public static InvalidOperationException Ambiguous(Type implementation, object best, object other) =>
        new(string.Join(Environment.NewLine, $"Unable to activate type '{implementation}'. The following constructors are ambiguous:", best, other));

    public static InvalidOperationException CannotResolve(Type parameter, Type implementation) =>
        new($"Unable to resolve service for type '{parameter}' while attempting to activate '{implementation}'.");

    public static InvalidOperationException InvalidServiceKeyType() =>
        new("The type of the key used for lookup doesn't match the type in the constructor parameter with the ServiceKey attribute.");

    public static InvalidOperationException InvalidDescriptor() => new("Invalid service descriptor");

    public static ArgumentException OpenGenericNeedsOpenImplementation(Type service, string paramName) =>
        new($"Open generic service type '{service}' requires registering an open generic implementation type.", paramName);

    public static ArgumentException ArityMismatch(Type service, Type implementation, string paramName) =>
        new($"Arity of open generic service type '{service}' does not equal arity of open generic implementation type '{implementation}'.", paramName);

    public static ArgumentException CannotInstantiate(Type implementation, Type service) =>
        new($"Cannot instantiate implementation type '{implementation}' for service type '{service}'.");

    public static InvalidOperationException ScopedInSingleton(Type scoped, Type singleton) =>
        new($"Cannot consume scoped service '{scoped}' from singleton '{singleton}'.");

    public static InvalidOperationException ScopedFromRoot(Type service, Type scoped) =>
        new($"Cannot resolve '{service}' from root provider because it requires scoped service '{scoped}'.");

    public static InvalidOperationException DirectScopedFromRoot(Type service) =>
        new($"Cannot resolve scoped service '{service}' from root provider.");

    public static InvalidOperationException AsyncDisposableOnly(Type type) =>
        new($"'{TypeNames.Display(type)}' type only implements IAsyncDisposable. Use DisposeAsync to dispose the container.");

    [DoesNotReturn]
    public static void ThrowAnyKeyForSingleService() =>
        throw new InvalidOperationException("KeyedService.AnyKey cannot be used to resolve a single service.");

    [DoesNotReturn]
    public static void ThrowNoService(Type type) =>
        throw new InvalidOperationException($"No service for type '{type}' has been registered.");

    [DoesNotReturn]
    public static void ThrowNoKeyedService(Type type, Type keyType) =>
        throw new InvalidOperationException($"No keyed service for type '{type}' using key type '{keyType}' has been registered.");

    [DoesNotReturn]
    public static void ThrowDisposed() => throw new ObjectDisposedException(nameof(IServiceProvider));
}

using System.Reflection;
using Microsoft.Extensions.DependencyInjection;

namespace Ladder.DI.Planning;

/// <summary>
/// Where a plan's result lives once created. The order matters: the "most transient" of several locations is the
/// largest value, which is how an <c>IEnumerable&lt;T&gt;</c> picks where to cache itself (the same order as
/// <c>CallSiteResultCacheLocation</c>).
/// </summary>
internal enum CacheLocation
{
    /// <summary>Singleton: one instance per container, created in the root scope.</summary>
    Root = 0,

    /// <summary>Scoped: one instance per scope (and one in the root scope, if resolved there).</summary>
    Scope = 1,

    /// <summary>Transient: a new instance every time, captured for disposal by the resolving scope.</summary>
    Dispose = 2,

    /// <summary>Not cached and not disposed: instances supplied by the caller, constants, the scope itself.</summary>
    None = 3,
}

/// <summary>
/// A resolution plan: a tree that says how to produce one service. Plans are built once per service and per
/// registration, then either interpreted (<see cref="Resolution.Interpreter"/>) or compiled to a delegate
/// (<see cref="Resolution.PlanCompiler"/>).
/// </summary>
internal abstract class Plan(Type serviceType, CacheLocation location)
{
    public Type ServiceType { get; } = serviceType;

    public CacheLocation Location { get; } = location;

    /// <summary>Index into each scope's instance array, for plans cached per scope; -1 otherwise.</summary>
    public int ScopeSlot { get; init; } = -1;

    /// <summary>
    /// The root-scope instance (singletons, and scoped services resolved from the root). Written once under a lock
    /// on this plan, read without one; null means "not created yet".
    /// </summary>
    public object? RootValue;

    /// <summary>
    /// The plan's body compiled to a delegate, set when a plan cached per scope is compiled, so a compiled caller can
    /// create it through <see cref="Scope.GetOrCreateScoped"/>.
    /// </summary>
    public Func<Scope, object?>? CompiledBody;

    /// <summary>
    /// The plan's cache identity as Microsoft's <c>ResultCache.Key</c> defines it: (service, slot) for what the planner
    /// caches (set by the planner), but (unkeyed service type, 0) for constants and the scope itself, which is the
    /// default here. Only scope validation uses it.
    /// </summary>
    public InstanceKey CacheKey { get; init; } = new(ServiceId.Of(serviceType), 0);

    /// <summary>
    /// Whether the produced object might need disposing. For a constructor this is known statically from the
    /// implementation type, which lets compiled code skip the capture call entirely for non-disposable transients.
    /// </summary>
    public virtual bool MayNeedDisposal => true;
}

/// <summary>A value known at planning time: a registered instance, a parameter's default value, a service key.</summary>
internal sealed class ConstantPlan(Type serviceType, object? value) : Plan(serviceType, CacheLocation.None)
{
    public object? Value { get; } = value;
}

/// <summary>The scope doing the resolving, injected as <see cref="IServiceProvider"/>.</summary>
internal sealed class ScopePlan() : Plan(typeof(IServiceProvider), CacheLocation.None);

internal sealed class ConstructorPlan(Type serviceType, CacheLocation location, ConstructorInfo constructor, Plan[] arguments)
    : Plan(serviceType, location)
{
    public ConstructorInfo Constructor { get; } = constructor;

    public Plan[] Arguments { get; } = arguments;

    public Type ImplementationType => Constructor.DeclaringType!;

    public override bool MayNeedDisposal =>
        typeof(IDisposable).IsAssignableFrom(ImplementationType) || typeof(IAsyncDisposable).IsAssignableFrom(ImplementationType);
}

/// <summary>A registered factory. Keyed factories also receive the key that was asked for.</summary>
internal sealed class FactoryPlan : Plan
{
    public FactoryPlan(Type serviceType, CacheLocation location, Func<IServiceProvider, object> factory)
        : base(serviceType, location) => Factory = factory;

    public FactoryPlan(Type serviceType, CacheLocation location, object? key, Func<IServiceProvider, object?, object> keyedFactory)
        : base(serviceType, location)
    {
        Key = key;
        KeyedFactory = keyedFactory;
    }

    public Func<IServiceProvider, object>? Factory { get; }

    public Func<IServiceProvider, object?, object>? KeyedFactory { get; }

    public object? Key { get; }
}

/// <summary><c>IEnumerable&lt;T&gt;</c>: an array of every matching registration, in registration order.</summary>
internal sealed class EnumerablePlan(Type serviceType, CacheLocation location, Type itemType, Plan[] items) : Plan(serviceType, location)
{
    public Type ItemType { get; } = itemType;

    public Plan[] Items { get; } = items;

    public override bool MayNeedDisposal => false;
}

internal static class Lifetimes
{
    public static CacheLocation ToLocation(this ServiceLifetime lifetime) => lifetime switch
    {
        ServiceLifetime.Singleton => CacheLocation.Root,
        ServiceLifetime.Scoped => CacheLocation.Scope,
        ServiceLifetime.Transient => CacheLocation.Dispose,
        _ => CacheLocation.None,
    };
}

using System.Reflection;
using System.Runtime.CompilerServices;
using Microsoft.Extensions.DependencyInjection;

namespace Ladder.DI.Planning;

/// <summary>
/// Turns registrations into resolution plans. Every rule here follows <c>ServiceLookup/CallSiteFactory.cs</c> in
/// dotnet/runtime release/10.0, because the specification suite and the differential tests hold us to its behaviour:
/// <list type="bullet">
/// <item>the last registration wins for a single service; <c>IEnumerable&lt;T&gt;</c> returns all, in registration order;</item>
/// <item>an exact (closed) registration beats an open generic one; only the last open generic is tried, and its
/// constraint violation throws, while <c>IEnumerable&lt;T&gt;</c> silently skips open generics whose constraints fail;</item>
/// <item>constructors are tried longest first; the first one whose every parameter is resolvable (or has a default)
/// wins, and any other satisfiable constructor must take a subset of its parameter types, or it is ambiguous;</item>
/// <item><c>KeyedService.AnyKey</c> registrations answer any non-null key for a single service but never appear in
/// enumerations, and an <c>AnyKey</c> enumeration lists every keyed registration but not the <c>AnyKey</c> ones.</item>
/// </list>
/// Instance identity is <see cref="InstanceKey"/> (service, slot), exactly as Microsoft keys its call sites, quirks
/// included: see the remarks on <see cref="TryEnumerable"/>.
/// Plans are built under one lock. That is only paid the first time each service is asked for; after that the
/// container serves it from its accessor cache without coming here.
/// </summary>
internal sealed class Planner : IServiceProviderIsKeyedService
{
    private const int DefaultSlot = 0;

    private readonly ServiceDescriptor[] _descriptors;
    private readonly Dictionary<ServiceId, int[]> _byId;
    private readonly Dictionary<InstanceKey, Plan> _plans = [];
    private readonly Lock _sync = new();
    private int _scopeSlots;

    public Planner(ICollection<ServiceDescriptor> descriptors)
    {
        // Copy: the caller may keep mutating its collection (the spec suite reverses it and builds a second provider).
        _descriptors = new ServiceDescriptor[descriptors.Count];
        descriptors.CopyTo(_descriptors, 0);

        var byId = new Dictionary<ServiceId, List<int>>();
        for (int i = 0; i < _descriptors.Length; i++)
        {
            ServiceDescriptor descriptor = _descriptors[i];
            Validate(descriptor, nameof(descriptors));
            ServiceId id = ServiceId.Of(descriptor);
            if (!byId.TryGetValue(id, out List<int>? indices))
            {
                byId[id] = indices = [];
            }

            indices.Add(i);
        }

        _byId = byId.ToDictionary(entry => entry.Key, entry => entry.Value.ToArray());
    }

    public IReadOnlyList<ServiceDescriptor> Descriptors => _descriptors;

    /// <summary>How many per-scope instance slots plans have claimed so far; scopes size their arrays from it.</summary>
    public int ScopeSlotCount => Volatile.Read(ref _scopeSlots);

    /// <summary>Services the container supplies itself. Like Microsoft's, they take precedence over registrations of the same type.</summary>
    public void AddBuiltIn(Type type, Plan plan)
    {
        lock (_sync)
        {
            _plans[new InstanceKey(ServiceId.Of(type), DefaultSlot)] = plan;
        }
    }

    public Plan? GetPlan(ServiceId id) => GetPlan(id, new ResolutionChain());

    /// <summary>The plan for one specific registration, as <c>ValidateOnBuild</c> checks every descriptor.</summary>
    public Plan GetPlan(int descriptorIndex)
    {
        ServiceDescriptor descriptor = _descriptors[descriptorIndex];
        ServiceId id = ServiceId.Of(descriptor);
        int[] group = _byId[id];

        // The registration's slot within its group: the last one is slot 0. (A descriptor object registered twice
        // takes the slot of its first occurrence, as ServiceDescriptorCacheItem.GetSlot does.)
        int position = Array.FindIndex(group, i => ReferenceEquals(_descriptors[i], descriptor));
        lock (_sync)
        {
            return CreateExact(descriptorIndex, id, new ResolutionChain(), group.Length - 1 - position);
        }
    }

    public bool IsService(Type serviceType) => IsService(new ServiceId(null, serviceType));

    public bool IsKeyedService(Type serviceType, object? serviceKey) => IsService(new ServiceId(serviceKey, serviceType));

    private bool IsService(ServiceId id)
    {
        ArgumentNullException.ThrowIfNull(id.Type);
        Type type = id.Type;
        if (type.IsGenericTypeDefinition)
        {
            return false; // an open generic can't be resolved, only its closed forms
        }

        if (_byId.ContainsKey(id) || (id.Key is not null && _byId.ContainsKey(new ServiceId(KeyedService.AnyKey, type))))
        {
            return true;
        }

        if (type.IsConstructedGenericType)
        {
            // IEnumerable<T> is always resolvable (possibly empty), even though nobody registers it.
            return type.GetGenericTypeDefinition() == typeof(IEnumerable<>) || _byId.ContainsKey(id.GenericDefinition());
        }

        return type == typeof(IServiceProvider) || type == typeof(IServiceScopeFactory)
            || type == typeof(IServiceProviderIsService) || type == typeof(IServiceProviderIsKeyedService);
    }

    private Plan? GetPlan(ServiceId id, ResolutionChain chain)
    {
        lock (_sync)
        {
            if (_plans.TryGetValue(new InstanceKey(id, DefaultSlot), out Plan? plan))
            {
                return plan;
            }

            chain.CheckCircularDependency(id);
            return TryExact(id, chain) ?? TryOpenGeneric(id, chain) ?? TryEnumerable(id, chain);
        }
    }

    private Plan? TryExact(ServiceId id, ResolutionChain chain)
    {
        if (_byId.TryGetValue(id, out int[]? indices)
            || (id.Key is not null && _byId.TryGetValue(new ServiceId(KeyedService.AnyKey, id.Type), out indices)))
        {
            // For an AnyKey registration the instance is keyed by the key actually asked for, so each key gets its own singleton.
            return CreateExact(indices[^1], id, chain, DefaultSlot);
        }

        return null;
    }

    private Plan? TryOpenGeneric(ServiceId id, ResolutionChain chain)
    {
        if (!id.Type.IsConstructedGenericType)
        {
            return null;
        }

        ServiceId definition = id.GenericDefinition();
        if (_byId.TryGetValue(definition, out int[]? indices)
            || (id.Key is not null && _byId.TryGetValue(new ServiceId(KeyedService.AnyKey, definition.Type), out indices)))
        {
            return CreateOpenGeneric(indices[^1], id, chain, DefaultSlot, throwOnConstraintViolation: true);
        }

        return null;
    }

    /// <remarks>
    /// Slots are handed out last-to-first, exact matches before open generics, so the element that gets slot 0 is
    /// the one a single resolution of the item would return, and they share an instance. Because the cache is keyed
    /// by (service, slot) rather than by registration, an enumeration can also <em>decide</em> a later single
    /// resolution: if the last open generic's constraints reject the type argument, a single resolution throws, but
    /// after an enumeration has put the last open generic that <em>does</em> fit into slot 0, the single resolution
    /// returns that instead. Microsoft's container behaves this way; the differential tests found it, and we match it.
    /// </remarks>
    private EnumerablePlan? TryEnumerable(ServiceId id, ResolutionChain chain)
    {
        if (!id.Type.IsConstructedGenericType || id.Type.GetGenericTypeDefinition() != typeof(IEnumerable<>))
        {
            return null;
        }

        chain.Add(id);
        try
        {
            Type itemType = id.Type.GenericTypeArguments[0];
            var itemId = new ServiceId(id.Key, itemType);
            bool anyKey = ReferenceEquals(id.Key, KeyedService.AnyKey);
            var items = new List<(int Index, Plan Plan)>();

            if (!itemType.IsConstructedGenericType && !anyKey && _byId.TryGetValue(itemId, out int[]? indices))
            {
                int slot = indices.Length; // the last registration gets slot 0
                foreach (int i in indices)
                {
                    items.Add((i, CreateExact(i, itemId, chain, --slot)));
                }
            }
            else
            {
                int slot = 0;
                Dictionary<ServiceId, int>? keyedSlots = null;

                for (int i = _descriptors.Length - 1; i >= 0; i--)
                {
                    ServiceDescriptor d = _descriptors[i];
                    if (KeysMatch(itemId.Key, d.ServiceKey) && d.ServiceType == itemType)
                    {
                        // An AnyKey enumeration resolves each registration under its own key, so its instances are
                        // the ones GetKeyedService(thatKey) returns, and each key counts its own slots.
                        ServiceId registration = anyKey ? ServiceId.Of(d) : itemId;
                        slot = SlotFor(registration);
                        items.Add((i, CreateExact(i, registration, chain, slot)));
                        Advance(registration);
                    }
                }

                for (int i = _descriptors.Length - 1; i >= 0; i--)
                {
                    ServiceDescriptor d = _descriptors[i];
                    if (KeysMatch(itemId.Key, d.ServiceKey) && itemType.IsConstructedGenericType && itemType.GetGenericTypeDefinition() == d.ServiceType)
                    {
                        // Under AnyKey this asks for the open definition itself, which can't be closed, so keyed
                        // open generics never appear in an AnyKey enumeration. Microsoft's container does the same.
                        ServiceId registration = anyKey ? ServiceId.Of(d) : itemId;
                        slot = SlotFor(registration);
                        if (CreateOpenGeneric(i, registration, chain, slot, throwOnConstraintViolation: false) is { } plan)
                        {
                            items.Add((i, plan));
                            Advance(registration);
                        }
                    }
                }

                items.Sort((a, b) => a.Index.CompareTo(b.Index));

                int SlotFor(ServiceId registration)
                {
                    if (!anyKey)
                    {
                        return slot;
                    }

                    keyedSlots ??= [];
                    return keyedSlots.TryAdd(registration, 0) ? 0 : keyedSlots[registration];
                }

                void Advance(ServiceId registration)
                {
                    if (anyKey)
                    {
                        keyedSlots![registration] = slot + 1;
                    }
                    else
                    {
                        slot++;
                    }
                }
            }

            // The array itself is cached as long-lived as its shortest-lived element allows: all singletons means
            // one array for the container's life, any scoped element means one per scope, anything else a new one
            // per resolution. Instances (constants) count as uncached, as in Microsoft's container.
            var location = CacheLocation.Root;
            foreach ((_, Plan plan) in items)
            {
                location = (CacheLocation)Math.Max((int)location, (int)plan.Location);
            }

            if (location is not (CacheLocation.Root or CacheLocation.Scope))
            {
                location = CacheLocation.None;
            }

            var enumerable = new EnumerablePlan(id.Type, location, itemType, [.. items.Select(item => item.Plan)]) { ScopeSlot = ClaimScopeSlot(location), CacheKey = new InstanceKey(id, DefaultSlot) };
            _plans[new InstanceKey(id, DefaultSlot)] = enumerable;
            return enumerable;
        }
        finally
        {
            chain.Remove(id);
        }

        static bool KeysMatch(object? lookupKey, object? descriptorKey)
        {
            if (lookupKey is null || descriptorKey is null)
            {
                return lookupKey is null && descriptorKey is null;
            }

            // AnyKey registrations are never enumerated; an AnyKey lookup matches every other key.
            return !descriptorKey.Equals(KeyedService.AnyKey)
                && (lookupKey.Equals(descriptorKey) || lookupKey.Equals(KeyedService.AnyKey));
        }
    }

    private Plan CreateExact(int index, ServiceId id, ResolutionChain chain, int slot)
    {
        var instanceKey = new InstanceKey(id, slot);
        if (_plans.TryGetValue(instanceKey, out Plan? plan))
        {
            return plan; // whatever already holds this (service, slot), even if another registration put it there
        }

        ServiceDescriptor d = _descriptors[index];
        CacheLocation location = d.Lifetime.ToLocation();
        if (ImplementationInstance(d) is { } instance)
        {
            // Supplied by the caller: never cached per scope, never disposed by the container.
            plan = new ConstantPlan(d.ServiceType, instance);
        }
        else if (!d.IsKeyedService && d.ImplementationFactory is { } factory)
        {
            plan = new FactoryPlan(d.ServiceType, location, factory) { ScopeSlot = ClaimScopeSlot(location), CacheKey = instanceKey };
        }
        else if (d.IsKeyedService && d.KeyedImplementationFactory is { } keyedFactory)
        {
            plan = new FactoryPlan(d.ServiceType, location, id.Key, keyedFactory) { ScopeSlot = ClaimScopeSlot(location), CacheKey = instanceKey };
        }
        else if (ImplementationType(d) is { } implementation)
        {
            plan = CreateConstructorPlan(location, id, implementation, chain, instanceKey);
        }
        else
        {
            throw Errors.InvalidDescriptor();
        }

        _plans[instanceKey] = plan;
        return plan;
    }

    private Plan? CreateOpenGeneric(int index, ServiceId id, ResolutionChain chain, int slot, bool throwOnConstraintViolation)
    {
        var instanceKey = new InstanceKey(id, slot);
        if (_plans.TryGetValue(instanceKey, out Plan? cached))
        {
            return cached;
        }

        ServiceDescriptor d = _descriptors[index];
        Type closed;
        try
        {
            closed = ImplementationType(d)!.MakeGenericType(id.Type.GenericTypeArguments);
        }
        catch (ArgumentException) when (!throwOnConstraintViolation)
        {
            return null; // the type arguments violate the implementation's constraints
        }

        ConstructorPlan plan = CreateConstructorPlan(d.Lifetime.ToLocation(), id, closed, chain, instanceKey);
        _plans[instanceKey] = plan;
        return plan;
    }

    private ConstructorPlan CreateConstructorPlan(CacheLocation location, ServiceId id, Type implementation, ResolutionChain chain, InstanceKey cacheKey)
    {
        chain.Add(id, implementation);
        try
        {
            ConstructorInfo[] constructors = implementation.GetConstructors();
            if (constructors.Length == 0)
            {
                throw Errors.NoConstructorMatch(implementation);
            }

            if (constructors.Length == 1)
            {
                ParameterInfo[] parameters = constructors[0].GetParameters();
                Plan[] arguments = parameters.Length == 0 ? [] : CreateArguments(id, implementation, chain, parameters, throwIfMissing: true)!;
                return new ConstructorPlan(id.Type, location, constructors[0], arguments) { ScopeSlot = ClaimScopeSlot(location), CacheKey = cacheKey };
            }

            // Longest first. Array.Sort with this comparison on GetConstructors()' order is what CallSiteFactory
            // does, so ties between equal-length constructors break the same way.
            Array.Sort(constructors, (a, b) => b.GetParameters().Length.CompareTo(a.GetParameters().Length));

            ConstructorInfo? best = null;
            Plan[]? bestArguments = null;
            HashSet<Type>? bestParameterTypes = null;
            foreach (ConstructorInfo constructor in constructors)
            {
                ParameterInfo[] parameters = constructor.GetParameters();
                if (CreateArguments(id, implementation, chain, parameters, throwIfMissing: false) is not { } arguments)
                {
                    continue;
                }

                if (best is null)
                {
                    best = constructor;
                    bestArguments = arguments;
                    continue;
                }

                // A shorter satisfiable constructor is fine only if the longest one already covers its parameters.
                bestParameterTypes ??= [.. best.GetParameters().Select(p => p.ParameterType)];
                if (parameters.Any(p => !bestParameterTypes.Contains(p.ParameterType)))
                {
                    throw Errors.Ambiguous(implementation, best, constructor);
                }
            }

            return best is null
                ? throw Errors.UnableToActivate(implementation)
                : new ConstructorPlan(id.Type, location, best, bestArguments!) { ScopeSlot = ClaimScopeSlot(location), CacheKey = cacheKey };
        }
        finally
        {
            chain.Remove(id);
        }
    }

    /// <returns>Null when a parameter can't be satisfied and <paramref name="throwIfMissing"/> is false.</returns>
    private Plan[]? CreateArguments(ServiceId id, Type implementation, ResolutionChain chain, ParameterInfo[] parameters, bool throwIfMissing)
    {
        var arguments = new Plan[parameters.Length];
        for (int i = 0; i < parameters.Length; i++)
        {
            Plan? argument = null;
            bool keyed = false;
            Type parameterType = parameters[i].ParameterType;
            foreach (object attribute in parameters[i].GetCustomAttributes(true))
            {
                // [ServiceKey] receives the key this service was resolved with; it is ignored for unkeyed resolutions.
                if (id.Key is not null && attribute is ServiceKeyAttribute)
                {
                    if (ReferenceEquals(id.Key, KeyedService.AnyKey))
                    {
                        parameterType = typeof(object);
                    }
                    else if (parameterType != id.Key.GetType() && parameterType != typeof(object))
                    {
                        throw Errors.InvalidServiceKeyType();
                    }

                    argument = new ConstantPlan(parameterType, id.Key);
                    break;
                }

                if (attribute is FromKeyedServicesAttribute fromKeyed)
                {
                    object? key = fromKeyed.LookupMode switch
                    {
                        ServiceKeyLookupMode.InheritKey => id.Key,
                        ServiceKeyLookupMode.ExplicitKey => fromKeyed.Key,
                        _ => null,
                    };

                    // A null key (NullKey mode, or InheritKey inside an unkeyed service) means an ordinary lookup.
                    if (key is not null)
                    {
                        argument = GetPlan(new ServiceId(key, parameterType), chain);
                        keyed = true;
                        break;
                    }
                }
            }

            if (!keyed)
            {
                argument ??= GetPlan(ServiceId.Of(parameterType), chain);
            }

            if (argument is null && TryGetDefaultValue(parameters[i], out object? defaultValue))
            {
                argument = new ConstantPlan(parameterType, defaultValue);
            }

            if (argument is null)
            {
                return throwIfMissing ? throw Errors.CannotResolve(parameterType, implementation) : null;
            }

            arguments[i] = argument;
        }

        return arguments;
    }

    /// <summary>
    /// A parameter's default value as the container passes it (<c>Common/src/Extensions/ParameterDefaultValue</c>):
    /// a struct parameter declared <c>= default</c> or <c>= new S()</c> reports a null DefaultValue, so it gets a zeroed
    /// instance, and a nullable enum's default comes back as its underlying integer, so it is converted back.
    /// </summary>
    private static bool TryGetDefaultValue(ParameterInfo parameter, out object? value)
    {
        value = null;
        if (!parameter.HasDefaultValue)
        {
            return false;
        }

        value = parameter.DefaultValue;
        Type type = parameter.ParameterType;
        Type? underlying = Nullable.GetUnderlyingType(type);
        if (value is null && type.IsValueType && underlying is null)
        {
            value = RuntimeHelpers.GetUninitializedObject(type);
        }

        if (value is not null && underlying is { IsEnum: true })
        {
            value = Enum.ToObject(underlying, value);
        }

        return true;
    }

    private int ClaimScopeSlot(CacheLocation location) => location == CacheLocation.Scope ? Interlocked.Increment(ref _scopeSlots) - 1 : -1;

    private static object? ImplementationInstance(ServiceDescriptor d) => d.IsKeyedService ? d.KeyedImplementationInstance : d.ImplementationInstance;

    private static Type? ImplementationType(ServiceDescriptor d) => d.IsKeyedService ? d.KeyedImplementationType : d.ImplementationType;

    /// <summary>Registration errors that can be seen without resolving anything, thrown when the container is built.</summary>
    private static void Validate(ServiceDescriptor descriptor, string paramName)
    {
        Type service = descriptor.ServiceType;
        Type? implementation = ImplementationType(descriptor);
        if (service.IsGenericTypeDefinition)
        {
            if (implementation is null || !implementation.IsGenericTypeDefinition)
            {
                throw Errors.OpenGenericNeedsOpenImplementation(service, paramName);
            }

            if (implementation.IsAbstract || implementation.IsInterface)
            {
                throw Errors.CannotInstantiate(implementation, service);
            }

            if (service.GetGenericArguments().Length != implementation.GetGenericArguments().Length)
            {
                throw Errors.ArityMismatch(service, implementation, paramName);
            }
        }
        else if (implementation is not null && (implementation.IsGenericTypeDefinition || implementation.IsAbstract || implementation.IsInterface))
        {
            throw Errors.CannotInstantiate(implementation, service);
        }
    }
}

using System.Text;

namespace Ladder.DI.Planning;

/// <summary>
/// The services currently being planned, in order. Asking for one that is already on the chain is a cycle, and it
/// is reported at planning time, before anything is constructed, with the path that led to it
/// (<c>ServiceLookup/CallSiteChain.cs</c>). Planning a service once makes later requests for it skip the chain,
/// because a finished plan is cycle-free.
/// </summary>
internal sealed class ResolutionChain
{
    private readonly Dictionary<ServiceId, (int Order, Type? Implementation)> _chain = [];

    public void CheckCircularDependency(ServiceId id)
    {
        if (_chain.ContainsKey(id))
        {
            throw Errors.CircularDependency(Describe(id));
        }
    }

    public void Add(ServiceId id, Type? implementation = null) => _chain[id] = (_chain.Count, implementation);

    public void Remove(ServiceId id) => _chain.Remove(id);

    private string Describe(ServiceId repeated)
    {
        var message = new StringBuilder()
            .Append("A circular dependency was detected for the service of type '").Append(TypeNames.Display(repeated.Type)).Append("'.")
            .AppendLine();
        foreach (var (id, (_, implementation)) in _chain.OrderBy(entry => entry.Value.Order))
        {
            message.Append(TypeNames.Display(id.Type));
            if (implementation is not null && implementation != id.Type)
            {
                message.Append('(').Append(TypeNames.Display(implementation)).Append(')');
            }

            message.Append(" -> ");
        }

        return message.Append(TypeNames.Display(repeated.Type)).ToString();
    }
}

using System.Collections.Concurrent;
using Microsoft.Extensions.DependencyInjection;

namespace Ladder.DI.Planning;

/// <summary>
/// <c>ValidateScopes</c>: refuses a singleton that would capture a scoped service (a "captive dependency"), and a
/// scoped service, or anything that needs one, resolved from the root provider, where it would silently live as long
/// as the container. Follows <c>ServiceLookup/CallSiteValidator.cs</c>: the first scoped service in each plan's tree is
/// worked out once and remembered, so the check on every resolution is one dictionary probe.
/// </summary>
/// <remarks>
/// The memo is keyed by <see cref="Plan.CacheKey"/>, as Microsoft's is keyed by <c>ResultCache.Key</c>, not by plan.
/// That matters: a constant (an instance registration, even a keyed one) has the key (unkeyed service type, 0), the
/// same as the unkeyed slot-0 registration of that type. So if that registration is scoped, a singleton depending on
/// a <em>keyed instance</em> of the type is reported as a captive dependency. It is a false positive in Microsoft's
/// container; the differential tests found it, and we reproduce it so the two containers fail the same builds.
/// </remarks>
internal sealed class ScopeValidator
{
    private readonly ConcurrentDictionary<InstanceKey, Type?> _firstScoped = new();

    /// <summary>Walks a newly built plan. Throws if a singleton in it depends, at any depth, on a scoped service.</summary>
    public void Validate(Plan plan) => Visit(plan, singleton: null);

    /// <summary>Called on every resolution when validation is on.</summary>
    public void ValidateResolution(Plan plan, Scope scope)
    {
        if (scope.IsRoot && _firstScoped.TryGetValue(plan.CacheKey, out Type? scoped) && scoped is not null)
        {
            throw plan.ServiceType == scoped ? Errors.DirectScopedFromRoot(scoped) : Errors.ScopedFromRoot(plan.ServiceType, scoped);
        }
    }

    private Type? Visit(Plan plan, Plan? singleton)
    {
        if (!_firstScoped.TryGetValue(plan.CacheKey, out Type? firstScoped))
        {
            firstScoped = VisitLocation(plan, singleton);
            _firstScoped[plan.CacheKey] = firstScoped;
        }

        if (firstScoped is not null && singleton is not null)
        {
            throw Errors.ScopedInSingleton(plan.ServiceType, singleton.ServiceType);
        }

        return firstScoped;
    }

    private Type? VisitLocation(Plan plan, Plan? singleton)
    {
        switch (plan.Location)
        {
            case CacheLocation.Root:
                return VisitChildren(plan, singleton: plan);
            case CacheLocation.Scope:
                // A singleton may hold the scope factory; that is how it is meant to create scopes.
                if (plan.ServiceType == typeof(IServiceScopeFactory))
                {
                    return null;
                }

                VisitChildren(plan, singleton);
                return plan.ServiceType;
            default:
                return VisitChildren(plan, singleton);
        }
    }

    private Type? VisitChildren(Plan plan, Plan? singleton)
    {
        Plan[] children = plan switch
        {
            ConstructorPlan constructor => constructor.Arguments,
            EnumerablePlan enumerable => enumerable.Items,
            _ => [],
        };

        Type? first = null;
        foreach (Plan child in children)
        {
            // Visit every child (not `first ??= Visit(...)`), so a captive dependency anywhere in the tree is found.
            Type? scoped = Visit(child, singleton);
            first ??= scoped;
        }

        return first;
    }
}

using System.Reflection;
using Ladder.DI.Planning;

namespace Ladder.DI.Resolution;

/// <summary>
/// Executes a plan by walking it, with reflection for constructors. It serves the first resolution of every service
/// (compiling something that may be asked for once is a loss), and all of them when compilation is turned off.
/// </summary>
internal static class Interpreter
{
    /// <summary>Resolves a plan in a scope, honouring where its result is cached.</summary>
    public static object? Resolve(Plan plan, Scope scope) => plan.Location switch
    {
        CacheLocation.Root => ResolveRoot(plan, scope.Root),
        CacheLocation.Scope => scope.GetOrCreateScoped(plan),
        CacheLocation.Dispose => plan.MayNeedDisposal ? scope.Capture(Create(plan, scope)) : Create(plan, scope),
        _ => Create(plan, scope),
    };

    /// <summary>
    /// The root instance of a singleton (or of a scoped service resolved from the root), created once under a lock
    /// on its plan. It is created <em>in the root scope</em>: its transient dependencies are captured by the root and
    /// an injected <see cref="IServiceProvider"/> is the root, whichever scope asked first (<c>VisitRootCache</c>).
    /// </summary>
    public static object? ResolveRoot(Plan plan, Scope root)
    {
        if (Volatile.Read(ref plan.RootValue) is { } value)
        {
            return value;
        }

        lock (plan)
        {
            if (plan.RootValue is { } raced)
            {
                return raced;
            }

            object? created = plan.CompiledBody is { } body ? body(root) : Create(plan, root);
            root.Capture(created);
            Volatile.Write(ref plan.RootValue, created);
            return created;
        }
    }

    /// <summary>Produces a new result of the plan, without consulting or filling any cache.</summary>
    public static object? Create(Plan plan, Scope scope)
    {
        switch (plan)
        {
            case ConstantPlan constant:
                return constant.Value;
            case ScopePlan:
                return scope;
            case ConstructorPlan constructor:
                Plan[] argumentPlans = constructor.Arguments;
                object?[] arguments = argumentPlans.Length == 0 ? [] : new object?[argumentPlans.Length];
                for (int i = 0; i < argumentPlans.Length; i++)
                {
                    arguments[i] = Resolve(argumentPlans[i], scope);
                }

                // DoNotWrapExceptions: a constructor's exception reaches the caller as itself, not as TargetInvocationException.
                return constructor.Constructor.Invoke(BindingFlags.DoNotWrapExceptions, binder: null, arguments, culture: null);
            case FactoryPlan factory:
                return factory.Factory is { } unkeyed ? unkeyed(scope) : factory.KeyedFactory!(scope, factory.Key);
            case EnumerablePlan enumerable:
                var array = Array.CreateInstance(enumerable.ItemType, enumerable.Items.Length);
                for (int i = 0; i < enumerable.Items.Length; i++)
                {
                    array.SetValue(Resolve(enumerable.Items[i], scope), i);
                }

                return array;
            default:
                throw new InvalidOperationException($"Unknown plan {plan.GetType()}.");
        }
    }
}

using System.Linq.Expressions;
using System.Reflection;
using Ladder.DI.Planning;

namespace Ladder.DI.Resolution;

/// <summary>
/// Compiles a plan into a <c>Func&lt;Scope, object?&gt;</c> with expression trees, so a warm resolution is straight-line
/// code: <c>new</c> calls with their arguments in place, no reflection, no argument arrays.
/// <list type="bullet">
/// <item>Singletons are embedded as constants (Microsoft's <c>ExpressionResolverBuilder</c> does the same). Compiling
/// on the second call means the first call has already created them.</item>
/// <item>Scoped services become a call to <see cref="Scope.GetOrCreateScoped"/>, whose slow path runs the scoped plan's
/// own compiled body.</item>
/// <item>A transient is wrapped in <see cref="Scope.Capture"/> only if its type can be disposable, which a constructor
/// plan knows statically, so non-disposable transients cost exactly their allocation.</item>
/// </list>
/// </summary>
internal static class PlanCompiler
{
    private static readonly MethodInfo GetOrCreateScoped = typeof(Scope).GetMethod(nameof(Scope.GetOrCreateScoped))!;
    private static readonly MethodInfo Capture = typeof(Scope).GetMethod(nameof(Scope.Capture))!;
    private static readonly MethodInfo ResolveRoot = typeof(Interpreter).GetMethod(nameof(Interpreter.ResolveRoot))!;

    /// <summary>Compiles a whole resolution: caching included, as <see cref="Interpreter.Resolve"/> would do it.</summary>
    public static Func<Scope, object?> Compile(Plan plan, Scope root)
    {
        ParameterExpression scope = Expression.Parameter(typeof(Scope), "scope");
        return Lambda(Resolve(plan, scope, root), scope);
    }

    private static Func<Scope, object?> Lambda(Expression body, ParameterExpression scope) =>
        Expression.Lambda<Func<Scope, object?>>(ConvertTo(body, typeof(object)), scope).Compile();

    private static Expression Resolve(Plan plan, ParameterExpression scope, Scope root)
    {
        switch (plan.Location)
        {
            case CacheLocation.Root:
                // An existing singleton is embedded. One that doesn't exist yet (only possible when compiling before
                // the first resolution) is created lazily at its turn, so creation and disposal order don't change.
                return Volatile.Read(ref plan.RootValue) is { } value
                    ? Constant(value)
                    : Expression.Call(ResolveRoot, Expression.Constant(plan, typeof(Plan)), Expression.Constant(root));
            case CacheLocation.Scope:
                if (plan.CompiledBody is null)
                {
                    // Compile the body once per plan; racing compilations produce equivalent delegates.
                    ParameterExpression bodyScope = Expression.Parameter(typeof(Scope), "scope");
                    plan.CompiledBody = Lambda(Create(plan, bodyScope, root), bodyScope);
                }

                return Expression.Call(scope, GetOrCreateScoped, Expression.Constant(plan));
            case CacheLocation.Dispose when plan.MayNeedDisposal:
                Expression created = Create(plan, scope, root);
                return ConvertTo(Expression.Call(scope, Capture, ConvertTo(created, typeof(object))), created.Type);
            default:
                return Create(plan, scope, root);
        }
    }

    private static Expression Create(Plan plan, ParameterExpression scope, Scope root)
    {
        switch (plan)
        {
            case ConstantPlan constant:
                return Constant(constant.Value);
            case ScopePlan:
                return scope;
            case ConstructorPlan constructor:
                ParameterInfo[] parameters = constructor.Constructor.GetParameters();
                var arguments = new Expression[parameters.Length];
                for (int i = 0; i < parameters.Length; i++)
                {
                    arguments[i] = ConvertTo(Resolve(constructor.Arguments[i], scope, root), parameters[i].ParameterType);
                }

                return Expression.New(constructor.Constructor, arguments);
            case FactoryPlan { Factory: { } factory }:
                return Expression.Invoke(Expression.Constant(factory), scope);
            case FactoryPlan { KeyedFactory: { } keyedFactory } keyed:
                return Expression.Invoke(Expression.Constant(keyedFactory), scope, Expression.Constant(keyed.Key, typeof(object)));
            case EnumerablePlan enumerable:
                return Expression.NewArrayInit(enumerable.ItemType, enumerable.Items.Select(item => ConvertTo(Resolve(item, scope, root), enumerable.ItemType)));
            default:
                throw new InvalidOperationException($"Unknown plan {plan.GetType()}.");
        }
    }

    /// <summary>A constant typed as its runtime type, so using it as an argument needs no cast.</summary>
    private static ConstantExpression Constant(object? value) => Expression.Constant(value, value?.GetType() ?? typeof(object));

    private static Expression ConvertTo(Expression expression, Type type)
    {
        bool reference = !expression.Type.IsValueType && !type.IsValueType;
        return expression.Type == type || (reference && type.IsAssignableFrom(expression.Type)) ? expression : Expression.Convert(expression, type);
    }
}

using Ladder.DI.Planning;
using Ladder.DI.Resolution;
using Microsoft.Extensions.DependencyInjection;

namespace Ladder.DI;

/// <summary>
/// One scope: its scoped instances and the disposables it must clean up. The root scope belongs to the container
/// and holds singletons' disposables (the singleton values themselves live on their plans). Scopes are flat, not
/// nested: a scope created from another scope is independent of it, and disposing the outer one leaves it alone.
/// </summary>
internal sealed class Scope : IServiceScope, IKeyedServiceProvider, IServiceScopeFactory, IAsyncDisposable
{
    /// <summary>Marks "resolved, and the factory returned null" in a slot, so null results are cached too.</summary>
    private static readonly object NullResult = new();

    private readonly ServiceContainer _container;
    private readonly Lock _sync = new();
    private object?[] _scoped = [];
    private List<object>? _disposables;
    private bool _disposed;

    public Scope(ServiceContainer container, bool isRoot)
    {
        _container = container;
        IsRoot = isRoot;
    }

    public bool IsRoot { get; }

    public Scope Root => _container.Root;

    public IServiceProvider ServiceProvider => this;

    internal bool IsDisposed => Volatile.Read(ref _disposed);

    public object? GetService(Type serviceType)
    {
        if (IsDisposed)
        {
            Errors.ThrowDisposed();
        }

        return _container.Resolve(serviceType, this);
    }

    public object? GetKeyedService(Type serviceType, object? serviceKey)
    {
        if (IsDisposed)
        {
            Errors.ThrowDisposed();
        }

        return _container.ResolveKeyed(serviceType, serviceKey, this);
    }

    public object GetRequiredKeyedService(Type serviceType, object? serviceKey)
    {
        if (IsDisposed)
        {
            Errors.ThrowDisposed();
        }

        return _container.ResolveRequiredKeyed(serviceType, serviceKey, this);
    }

    public IServiceScope CreateScope() => _container.CreateScope();

    /// <summary>
    /// The scope's instance of a scoped plan, created on first use. Reads are lock-free: a slot is written once,
    /// under the lock, with a release store, so a reader either sees the finished instance or takes the lock.
    /// </summary>
    public object? GetOrCreateScoped(Plan plan)
    {
        if (IsRoot)
        {
            // A scoped service resolved from the root lives as long as the root, exactly like a singleton.
            return Interpreter.ResolveRoot(plan, this);
        }

        int slot = plan.ScopeSlot;
        object?[] slots = Volatile.Read(ref _scoped);
        if ((uint)slot < (uint)slots.Length && Volatile.Read(ref slots[slot]) is { } existing)
        {
            return ReferenceEquals(existing, NullResult) ? null : existing;
        }

        lock (_sync)
        {
            slots = _scoped;
            if ((uint)slot < (uint)slots.Length && slots[slot] is { } raced)
            {
                return ReferenceEquals(raced, NullResult) ? null : raced;
            }

            object? value = plan.CompiledBody is { } body ? body(this) : Interpreter.Create(plan, this);
            Capture(value);

            // Creating the value may have created other scoped services and grown the array, so look again.
            slots = _scoped;
            if (slot >= slots.Length)
            {
                var grown = new object?[Math.Max(Math.Max(slot + 1, _container.Planner.ScopeSlotCount), slots.Length * 2)];
                slots.CopyTo(grown, 0);
                Volatile.Write(ref _scoped, grown);
                slots = grown;
            }

            Volatile.Write(ref slots[slot], value ?? NullResult);
            return value;
        }
    }

    /// <summary>
    /// Registers a service this scope created for disposal. Order of capture is order of creation finishing, so a
    /// service's dependencies are captured before it, and the reverse walk in Dispose tears dependents down first.
    /// </summary>
    public object? Capture(object? service)
    {
        if (service is null || ReferenceEquals(service, this) || service is not (IDisposable or IAsyncDisposable))
        {
            return service;
        }

        bool disposed;
        lock (_sync)
        {
            disposed = _disposed;
            if (!disposed)
            {
                (_disposables ??= []).Add(service);
            }
        }

        if (disposed)
        {
            // The scope was disposed while this was being created: clean it up rather than leak it, then fail.
            if (service is IDisposable disposable)
            {
                disposable.Dispose();
            }
            else
            {
                Task.Run(() => ((IAsyncDisposable)service).DisposeAsync().AsTask()).GetAwaiter().GetResult();
            }

            Errors.ThrowDisposed();
        }

        return service;
    }

    public void Dispose()
    {
        List<object>? toDispose = BeginDispose();
        if (toDispose is null)
        {
            return;
        }

        for (int i = toDispose.Count - 1; i >= 0; i--)
        {
            if (toDispose[i] is IDisposable disposable)
            {
                disposable.Dispose();
            }
            else
            {
                // Sync disposal can't honour an IAsyncDisposable-only service; say so instead of blocking on it.
                throw Errors.AsyncDisposableOnly(toDispose[i].GetType());
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        List<object>? toDispose = BeginDispose();
        if (toDispose is null)
        {
            return;
        }

        for (int i = toDispose.Count - 1; i >= 0; i--)
        {
            if (toDispose[i] is IAsyncDisposable asyncDisposable)
            {
                await asyncDisposable.DisposeAsync().ConfigureAwait(false);
            }
            else
            {
                ((IDisposable)toDispose[i]).Dispose();
            }
        }
    }

    private List<object>? BeginDispose()
    {
        lock (_sync)
        {
            if (_disposed)
            {
                return null;
            }

            // From here on Capture disposes anything new immediately; the list no longer changes.
            _disposed = true;
        }

        if (IsRoot)
        {
            _container.MarkDisposed();
        }

        return _disposables;
    }
}

using Microsoft.Extensions.DependencyInjection;

namespace Ladder.DI;

public static class ServiceCollectionExtensions
{
    /// <summary>Builds a <see cref="ServiceContainer"/>; the counterpart of <c>BuildServiceProvider()</c>.</summary>
    public static ServiceContainer BuildLadderServiceProvider(this IServiceCollection services, ServiceContainerOptions? options = null) =>
        new(services, options ?? new ServiceContainerOptions());
}

using System.Collections.Concurrent;
using Ladder.DI.Planning;
using Ladder.DI.Resolution;
using Microsoft.Extensions.DependencyInjection;

namespace Ladder.DI;

/// <summary>How warm resolutions run.</summary>
public enum ResolutionMode
{
    /// <summary>Interpret the first resolution of each service, compile it to a delegate on the second (the default).</summary>
    Compiled,

    /// <summary>Compile before the first resolution. Same behaviour, every call compiled; used to run the conformance suite through the compiler.</summary>
    CompiledOnFirstCall,

    /// <summary>Always walk the plan with reflection. Kept for comparison and for platforms without dynamic code.</summary>
    Interpreted,
}

public sealed class ServiceContainerOptions
{
    /// <summary>Refuse singletons that capture scoped services, and scoped services resolved from the root.</summary>
    public bool ValidateScopes { get; init; }

    /// <summary>Plan every registration when the container is built, so missing dependencies and cycles fail early.</summary>
    public bool ValidateOnBuild { get; init; }

    public ResolutionMode Mode { get; init; } = ResolutionMode.Compiled;
}

/// <summary>
/// A dependency injection container built from an <see cref="IServiceCollection"/>. Resolving goes:
/// accessor cache (one dictionary probe) → accessor delegate. Building an accessor goes: <see cref="Planner"/> builds
/// the plan (cycles and unresolvable constructors fail here), the plan is validated if asked, and the accessor
/// interprets it once and then compiles it. A singleton's accessor is just its value.
/// </summary>
public sealed class ServiceContainer : IKeyedServiceProvider, IDisposable, IAsyncDisposable
{
    private readonly ServiceContainerOptions _options;
    private readonly ScopeValidator? _validator;

    // Unkeyed lookups are the hot path, so they get a dictionary keyed by Type alone: no struct key to hash and compare.
    private readonly ConcurrentDictionary<Type, Accessor> _unkeyed = new();
    private readonly ConcurrentDictionary<ServiceId, Accessor> _keyed = new();
    private readonly Func<Type, Accessor> _createUnkeyed;
    private readonly Func<ServiceId, Accessor> _createKeyed;
    private volatile bool _disposed;

    public ServiceContainer(IServiceCollection services)
        : this(services, new ServiceContainerOptions())
    {
    }

    public ServiceContainer(IServiceCollection services, ServiceContainerOptions options)
    {
        ArgumentNullException.ThrowIfNull(services);
        ArgumentNullException.ThrowIfNull(options);
        _options = options;
        _validator = options.ValidateScopes ? new ScopeValidator() : null;
        _createUnkeyed = type => CreateAccessor(ServiceId.Of(type));
        _createKeyed = CreateAccessor;
        Root = new Scope(this, isRoot: true);
        Planner = new Planner(services);

        // Built-in services. IServiceProvider is whichever scope is resolving; the rest are container-wide.
        Planner.AddBuiltIn(typeof(IServiceProvider), new ScopePlan());
        Planner.AddBuiltIn(typeof(IServiceScopeFactory), new ConstantPlan(typeof(IServiceScopeFactory), Root));
        Planner.AddBuiltIn(typeof(IServiceProviderIsService), new ConstantPlan(typeof(IServiceProviderIsService), Planner));
        Planner.AddBuiltIn(typeof(IServiceProviderIsKeyedService), new ConstantPlan(typeof(IServiceProviderIsKeyedService), Planner));

        if (options.ValidateOnBuild)
        {
            ValidateAll();
        }
    }

    internal Planner Planner { get; }

    internal Scope Root { get; }

    public object? GetService(Type serviceType) => Resolve(serviceType, Root);

    public object? GetKeyedService(Type serviceType, object? serviceKey) => ResolveKeyed(serviceType, serviceKey, Root);

    public object GetRequiredKeyedService(Type serviceType, object? serviceKey) => ResolveRequiredKeyed(serviceType, serviceKey, Root);

    public void Dispose() => Root.Dispose();

    public ValueTask DisposeAsync() => Root.DisposeAsync();

    internal IServiceScope CreateScope()
    {
        if (_disposed)
        {
            Errors.ThrowDisposed();
        }

        return new Scope(this, isRoot: false);
    }

    internal void MarkDisposed() => _disposed = true;

    internal object? Resolve(Type serviceType, Scope scope)
    {
        if (_disposed)
        {
            Errors.ThrowDisposed();
        }

        if (!_unkeyed.TryGetValue(serviceType, out Accessor? accessor))
        {
            accessor = _unkeyed.GetOrAdd(serviceType, _createUnkeyed);
        }

        return Invoke(accessor, scope);
    }

    internal object? ResolveKeyed(Type serviceType, object? serviceKey, Scope scope)
    {
        if (serviceKey is null)
        {
            return Resolve(serviceType, scope); // a null key is the unkeyed service
        }

        // AnyKey can enumerate (IEnumerable<T>) but never pick one service.
        if (ReferenceEquals(serviceKey, KeyedService.AnyKey)
            && !(serviceType.IsGenericType && serviceType.GetGenericTypeDefinition() == typeof(IEnumerable<>)))
        {
            Errors.ThrowAnyKeyForSingleService();
        }

        if (_disposed)
        {
            Errors.ThrowDisposed();
        }

        var id = new ServiceId(serviceKey, serviceType);
        if (!_keyed.TryGetValue(id, out Accessor? accessor))
        {
            accessor = _keyed.GetOrAdd(id, _createKeyed);
        }

        return Invoke(accessor, scope);
    }

    internal object ResolveRequiredKeyed(Type serviceType, object? serviceKey, Scope scope)
    {
        object? service = ResolveKeyed(serviceType, serviceKey, scope);
        if (service is null)
        {
            if (serviceKey is null)
            {
                Errors.ThrowNoService(serviceType);
            }

            Errors.ThrowNoKeyedService(serviceType, serviceKey.GetType());
        }

        return service;
    }

    private object? Invoke(Accessor accessor, Scope scope)
    {
        if (_validator is not null && accessor.Plan is { } plan)
        {
            _validator.ValidateResolution(plan, scope);
        }

        return accessor.Resolver(scope);
    }

    private Accessor CreateAccessor(ServiceId id)
    {
        Plan? plan = Planner.GetPlan(id);
        if (plan is null)
        {
            return Accessor.Missing;
        }

        _validator?.Validate(plan);

        if (plan.Location == CacheLocation.Root)
        {
            // A singleton never changes once created, so its accessor is its value: nothing to interpret or compile.
            object? value = Interpreter.ResolveRoot(plan, Root);
            return new Accessor(plan, _ => value);
        }

        return _options.Mode switch
        {
            ResolutionMode.Interpreted => new Accessor(plan, scope => Interpreter.Resolve(plan, scope)),
            ResolutionMode.CompiledOnFirstCall => new Accessor(plan, PlanCompiler.Compile(plan, Root)),
            _ => Accessor.CompileOnSecondCall(plan, Root),
        };
    }

    private void ValidateAll()
    {
        var errors = new List<Exception>();
        for (int i = 0; i < Planner.Descriptors.Count; i++)
        {
            ServiceDescriptor descriptor = Planner.Descriptors[i];
            if (descriptor.ServiceType.IsGenericTypeDefinition)
            {
                continue; // open generics can only be checked once closed
            }

            try
            {
                Plan plan = Planner.GetPlan(i);
                _validator?.Validate(plan);
            }
            catch (Exception e)
            {
                errors.Add(new InvalidOperationException($"Error while validating the service descriptor '{descriptor}': {e.Message}", e));
            }
        }

        if (errors.Count > 0)
        {
            throw new AggregateException("Some services are not able to be constructed", errors);
        }
    }

    private sealed class Accessor(Plan? plan, Func<Scope, object?> resolver)
    {
        public static readonly Accessor Missing = new(null, _ => null);

        private int _calls;

        public Plan? Plan { get; } = plan;

        public Func<Scope, object?> Resolver { get; private set; } = resolver;

        /// <summary>
        /// Interprets, and on the second call compiles. One-shot services never pay for compilation. Unlike
        /// Microsoft's container, which compiles on a thread-pool thread, this compiles inline: the second caller
        /// pays once, and there is no window where two engines run the same service.
        /// </summary>
        public static Accessor CompileOnSecondCall(Plan plan, Scope root)
        {
            var accessor = new Accessor(plan, null!);
            accessor.Resolver = scope =>
            {
                object? result = Interpreter.Resolve(plan, scope);
                if (Interlocked.Increment(ref accessor._calls) == 2)
                {
                    accessor.Resolver = PlanCompiler.Compile(plan, root);
                }

                return result;
            };
            return accessor;
        }
    }
}

using Microsoft.Extensions.DependencyInjection;

namespace Ladder.DI;

/// <summary>
/// What a caller asks for: a service type plus an optional key. A null key means "not keyed", which is how the
/// contract lets <c>GetKeyedService(type, null)</c> and <c>GetService(type)</c> mean the same thing.
/// Equality follows <c>ServiceLookup/ServiceIdentifier.cs</c>: keys compare with <see cref="object.Equals(object)"/>.
/// </summary>
internal readonly struct ServiceId(object? key, Type type) : IEquatable<ServiceId>
{
    public object? Key { get; } = key;

    public Type Type { get; } = type;

    public static ServiceId Of(Type type) => new(null, type);

    public static ServiceId Of(ServiceDescriptor descriptor) => new(descriptor.ServiceKey, descriptor.ServiceType);

    public ServiceId GenericDefinition() => new(Key, Type.GetGenericTypeDefinition());

    public bool Equals(ServiceId other) =>
        Type == other.Type && (Key is null ? other.Key is null : other.Key is not null && Key.Equals(other.Key));

    public override bool Equals(object? obj) => obj is ServiceId other && Equals(other);

    public override int GetHashCode() => Key is null ? Type.GetHashCode() : HashCode.Combine(Type, Key);

    public override string ToString() => Key is null ? Type.ToString() : $"({Key}, {Type})";
}

/// <summary>
/// The identity of a plan, and so of the singleton or scoped instance it produces: the service asked for, plus a slot
/// that counts registrations of it from the last one (slot 0) backwards. A single resolution is slot 0, so
/// <c>GetService&lt;T&gt;()</c> and the last element of <c>IEnumerable&lt;T&gt;</c> are the same object. This is
/// Microsoft's <c>ServiceCacheKey</c>. Keying by registration instead looks equivalent but isn't; see
/// <c>Planner.TryEnumerable</c>.
/// </summary>
internal readonly record struct InstanceKey(ServiceId Service, int Slot);

