namespace Ladder.DI.Tests;

/// <summary>
/// Claim 2: on random service graphs, ours and Microsoft's container (10.0.13, the reference implementation) agree
/// on everything a caller can observe: which resolutions share an instance, the order instances are created and
/// disposed in, and the type and kind of every exception, including at build time with ValidateOnBuild and
/// ValidateScopes. Our resolution engine is drawn at random per graph.
/// </summary>
public partial class DifferentialTests(ITestOutputHelper output)
{
    // 10,000 is the claim. LADDER_DI_GRAPHS lowers it for mutation testing, where the suite runs once per mutant.
    private static readonly int Graphs = int.TryParse(Environment.GetEnvironmentVariable("LADDER_DI_GRAPHS"), out int n) ? n : 10_000;

    private static readonly Gen<bool> s_sometimes = Gen.Int[0, 3].Select(i => i == 0);

    private static readonly Template[] s_disposables = [Template.Disposable, Template.AsyncDisposable, Template.BothDisposable, Template.OpenDisposable];

    // Disposal order is half of what is claimed, so disposable implementations are drawn more often than the rest.
    private static readonly Gen<Template> s_template = Gen.Frequency(
        (7, Gen.Enum<Template>()),
        (3, Gen.Int[0, s_disposables.Length - 1].Select(i => s_disposables[i])));

    private static readonly Gen<Registration> s_registration = Gen.Select(
        Gen.Int[0, Scenario.Services - 1], Gen.Enum<ServiceLifetime>(), s_template, Gen.Int[0, 3], Gen.Int[0, 2 * Scenario.Services], Gen.Int[0, 2 * Scenario.Services],
        (service, lifetime, template, key, a, b) => new Registration(service, lifetime, template, key, a, b));

    // Mostly resolutions; scopes are created often enough to matter and disposed now and then.
    private static readonly Gen<OpKind> s_opKind = Gen.Frequency(
        (5, Gen.Const(OpKind.Get)), (3, Gen.Const(OpKind.GetKeyed)), (3, Gen.Const(OpKind.GetAll)), (2, Gen.Const(OpKind.GetAllKeyed)),
        (2, Gen.Const(OpKind.GetRequired)), (3, Gen.Const(OpKind.CreateScope)), (1, Gen.Const(OpKind.Dispose)), (1, Gen.Const(OpKind.DisposeAsync)));

    private static readonly Gen<Op> s_op = Gen.Select(
        s_opKind, Gen.Int[0, Scenario.Services - 1], Gen.Int[0, Scenario.Keys.Length - 1], Gen.Int[0, 7],
        (kind, service, key, scope) => new Op(kind, service, key, scope));

    private static readonly Gen<Scenario> s_scenario = Gen.Select(
        Gen.Bool, s_sometimes, s_sometimes, Gen.Enum<ResolutionMode>(), s_registration.Array[0, 14], s_op.Array[1, 30], Gen.Bool,
        (acyclic, validateScopes, validateOnBuild, mode, registrations, ops, async) => new Scenario(acyclic, validateScopes, validateOnBuild, mode, registrations, ops, async));

    [Fact]
    public void Random_graphs_resolve_and_dispose_exactly_like_Microsofts_container()
    {
        var stats = new Stats();
        s_scenario.Sample(
            scenario =>
            {
                string expected = ScenarioRunner.Run(scenario, (services, s) =>
                    services.BuildServiceProvider(new ServiceProviderOptions { ValidateScopes = s.ValidateScopes, ValidateOnBuild = s.ValidateOnBuild }));
                if (expected.Contains(MicrosoftDuplicateCacheKey, StringComparison.Ordinal))
                {
                    // A Microsoft bug we don't copy: see ContainerTests.Scoped_AnyKey_service_that_depends_on_its_own_keyed_enumerable_does_not_throw.
                    stats.AddMicrosoftBug(scenario.ToString());
                    return;
                }

                string actual = ScenarioRunner.Run(scenario, (services, s) =>
                    services.BuildLadderServiceProvider(new ServiceContainerOptions { ValidateScopes = s.ValidateScopes, ValidateOnBuild = s.ValidateOnBuild, Mode = s.Mode }));
                Assert.True(Describer.Comparable(expected) == Describer.Comparable(actual), $"Microsoft's container:\n{expected}\n\nours:\n{actual}");
                stats.Add(Describer.Comparable(expected));
            },
            iter: Graphs,
            print: scenario => scenario.ToString());

        // The generator must actually reach the interesting regions, or agreement means little.
        output.WriteLine(stats.ToString());
        output.WriteLine(stats.Examples());
        // About 1 graph in 200,000 hits the Microsoft bug (2 of ~390,000 on 2026-11-02); more than a handful would mean the filter hides something else.
        Assert.Equal(Graphs, stats.Count("graphs") + stats.Count("microsoft-bug"));
        Assert.True(stats.Count("microsoft-bug") <= Math.Max(1, Graphs / 1_000), stats.ToString());
        (string What, int AtLeast)[] floors =
        [
            ("shared", 1_000), ("disposals>=3", 1_000), (":cycle", 100), (":ambiguous", 10), (":captive", 50), (":scoped-from-root", 50),
            ("build !", 50), (":async-only", 10), ("!ArgumentException", 10), ("!ObjectDisposedException", 100), ("!NotSupportedException", 100), (":key-type", 1),
        ];
        foreach ((string what, int atLeast) in floors)
        {
            Assert.True(stats.Count(what) >= Math.Max(1, (long)atLeast * Graphs / 10_000), $"only {stats.Count(what)} graphs with {what}\n{stats}");
        }
    }

    /// <summary>Microsoft's internal cache-key collision (draft upstream report (c) in evidence/upstream).</summary>
    private const string MicrosoftDuplicateCacheKey = "!ArgumentException {An item with the same key has already been added. Key: Microsoft.Extensions.DependencyInjection.ServiceLookup.ServiceCacheKey}";

    [GeneratedRegex(@"[(,\[] ?#\d+")]
    private static partial Regex SharedInstance();

    [GeneratedRegex(@"disposals [DA]\d+,[DA]\d+,[DA]\d+")]
    private static partial Regex ThreeDisposals();

    /// <summary>How many graphs' (agreed-upon) observations contained each kind of event.</summary>
    private sealed class Stats
    {
        private static readonly string[] Markers =
        [
            ":cycle", ":ambiguous", ":captive", ":scoped-from-root", ":unresolvable", ":no-satisfiable-constructor", ":anykey", ":missing",
            ":async-only", ":key-type", ":other", "build !", "!ArgumentException", "!ObjectDisposedException", "!NotSupportedException",
        ];

        private readonly ConcurrentDictionary<string, int> _counts = new();
        private readonly ConcurrentDictionary<string, string> _examples = new();

        public int Count(string what) => _counts.GetValueOrDefault(what);

        public void Add(string observations)
        {
            Bump("graphs");
            if (SharedInstance().IsMatch(observations))
            {
                Bump("shared"); // some resolution returned an instance already seen
            }

            if (ThreeDisposals().IsMatch(observations))
            {
                Bump("disposals>=3");
            }

            foreach (string marker in Markers.Where(m => observations.Contains(m, StringComparison.Ordinal)))
            {
                Bump(marker);
                _examples.TryAdd(marker, observations);
            }
        }

        public void AddMicrosoftBug(string scenario)
        {
            Bump("microsoft-bug");
            _examples.TryAdd("microsoft-bug", scenario);
        }

        public string Examples() => string.Join("\n\n", _examples.OrderBy(e => e.Key, StringComparer.Ordinal).Select(e => $"--- first graph with {e.Key}:\n{e.Value}"));

        public override string ToString() => string.Join("; ", _counts.OrderBy(c => c.Key, StringComparer.Ordinal).Select(c => $"{c.Key} {c.Value}"));

        private void Bump(string what) => _counts.AddOrUpdate(what, 1, (_, n) => n + 1);
    }
}

using Microsoft.Extensions.DependencyInjection;

namespace Ladder.DI.Tests.Graph;

// The building blocks of random service graphs. Services are IS<K0>..IS<K5>; implementations are generic templates
// closed over a marker (which service they implement) and over their dependency types, so a generated graph is just
// data plus MakeGenericType. Every node takes the run's RunLog, which numbers it in creation order and records its
// disposal, so two containers can be compared on "same instances, created and disposed in the same order".

public interface IMarked;

public sealed class K0 : IMarked;

public sealed class K1;

public sealed class K2 : IMarked;

public sealed class K3;

public sealed class K4 : IMarked;

public sealed class K5;

#pragma warning disable CA1040 // a service with no members: identity is all that's compared
public interface IS<T>;
#pragma warning restore CA1040

/// <summary>Per-run recorder, registered as an instance, so every node can reach it without statics.</summary>
public sealed class RunLog
{
    private int _next;

    public List<string> Disposals { get; } = [];

    public int Created() => _next++;
}

public abstract class Node
{
    protected Node(RunLog log, params object?[] parts)
    {
        Log = log;
        Id = log.Created();
        Parts = parts;
    }

    public RunLog Log { get; }

    public int Id { get; }

    /// <summary>What was injected, in parameter order (dependencies, providers, keys, enumerations).</summary>
    public object?[] Parts { get; }
}

public sealed class Leaf<T>(RunLog log) : Node(log), IS<T>;

public sealed class Dep1<T, A>(RunLog log, A a) : Node(log, a), IS<T>;

public sealed class Dep2<T, A, B>(RunLog log, A a, B b) : Node(log, a, b), IS<T>;

public sealed class Many<T, A>(RunLog log, IEnumerable<A> all) : Node(log, all), IS<T>;

public sealed class WithProvider<T>(RunLog log, IServiceProvider provider) : Node(log, provider), IS<T>;

public sealed class Disposable<T, A>(RunLog log, A a) : Node(log, a), IS<T>, IDisposable
{
    public void Dispose() => Log.Disposals.Add($"D{Id}");
}

public sealed class AsyncDisposable<T, A>(RunLog log, A a) : Node(log, a), IS<T>, IAsyncDisposable
{
    public ValueTask DisposeAsync()
    {
        Log.Disposals.Add($"A{Id}");
        return ValueTask.CompletedTask;
    }
}

public sealed class BothDisposable<T, A>(RunLog log, A a) : Node(log, a), IS<T>, IDisposable, IAsyncDisposable
{
    public void Dispose() => Log.Disposals.Add($"D{Id}");

    public ValueTask DisposeAsync()
    {
        Log.Disposals.Add($"A{Id}");
        return ValueTask.CompletedTask;
    }
}

/// <summary>Constructor selection: the longest satisfiable constructor wins when the others are subsets of it.</summary>
public sealed class Longest<T, A, B> : Node, IS<T>
{
    public Longest(RunLog log, A a)
        : base(log, "A", a)
    {
    }

    public Longest(RunLog log, B b)
        : base(log, "B", b)
    {
    }

    public Longest(RunLog log, A a, B b)
        : base(log, "AB", a, b)
    {
    }
}

/// <summary>Constructor selection: ambiguous when both A and B are resolvable.</summary>
public sealed class Either<T, A, B> : Node, IS<T>
{
    public Either(RunLog log, A a)
        : base(log, "A", a)
    {
    }

    public Either(RunLog log, B b)
        : base(log, "B", b)
    {
    }
}

public sealed class KeyedDep<T, A>(RunLog log, [FromKeyedServices("k1")] A a) : Node(log, a), IS<T>;

public sealed class InheritedKeyDep<T, A>(RunLog log, [FromKeyedServices] A a) : Node(log, a), IS<T>;

public sealed class KeyAware<T>(RunLog log, [ServiceKey] object? key = null) : Node(log, key), IS<T>;

/// <summary>A [ServiceKey] of the wrong type for every key the graphs use (strings): refused whenever resolved with a key.</summary>
public sealed class IntKeyAware<T>(RunLog log, [ServiceKey] int key = 0) : Node(log, key), IS<T>;

public sealed class Optional<T, A>(RunLog log, A? a = null) : Node(log, a), IS<T>
    where A : class;

/// <summary>Creates its dependency, then fails: what was created before the failure must still be disposed.</summary>
public sealed class Throws<T, A> : Node, IS<T>
{
    public Throws(RunLog log, A a)
        : base(log, a) => throw new NotSupportedException($"node {Id} refuses to be built");
}

public sealed class Open<T>(RunLog log) : Node(log), IS<T>;

public sealed class OpenDisposable<T>(RunLog log) : Node(log), IS<T>, IDisposable
{
    public void Dispose() => Log.Disposals.Add($"D{Id}");
}

public sealed class OpenConstrained<T>(RunLog log) : Node(log), IS<T>
    where T : IMarked;

using System.Collections;
using System.Text;
using Microsoft.Extensions.DependencyInjection;

namespace Ladder.DI.Tests.Graph;

public enum Template
{
    Leaf, Dep1, Dep2, Many, WithProvider, Disposable, AsyncDisposable, BothDisposable, Longest, Either,
    KeyedDep, InheritedKeyDep, KeyAware, IntKeyAware, Optional, Throws, Factory, Instance, Open, OpenDisposable, OpenConstrained,
}

public enum OpKind { Get, GetKeyed, GetAll, GetAllKeyed, GetRequired, CreateScope, Dispose, DisposeAsync }

/// <summary>
/// One registration. <see cref="Key"/> indexes <see cref="Scenario.Keys"/>; <see cref="DepA"/>/<see cref="DepB"/>
/// encode a dependency: below <see cref="Scenario.Services"/> a service, below twice that an <c>IEnumerable</c> of
/// one, otherwise the RunLog.
/// </summary>
public sealed record Registration(int Service, ServiceLifetime Lifetime, Template Template, int Key, int DepA, int DepB);

public sealed record Op(OpKind Kind, int Service, int Key, int Scope);

/// <summary>
/// A random service graph and a script to run against it. In acyclic scenarios every dependency points to a
/// lower-numbered service and factories resolve dependencies through the provider; in cyclic ones dependencies may
/// point anywhere (so cycles are planned and must be refused) and factories resolve nothing, because a cycle through
/// a factory is invisible to planning and overflows the stack in every container.
/// </summary>
public sealed record Scenario(bool Acyclic, bool ValidateScopes, bool ValidateOnBuild, ResolutionMode Mode, Registration[] Registrations, Op[] Ops, bool DisposeRootAsync)
{
    public const int Services = 6;

    public static readonly Type[] Markers = [typeof(K0), typeof(K1), typeof(K2), typeof(K3), typeof(K4), typeof(K5)];

    /// <summary>Registration keys use the first four; operations also ask for "k3", which nothing registers.</summary>
    public static readonly object?[] Keys = [null, "k1", "k2", KeyedService.AnyKey, "k3"];

    public override string ToString() =>
        $"Acyclic={Acyclic} ValidateScopes={ValidateScopes} ValidateOnBuild={ValidateOnBuild} Mode={Mode} DisposeRootAsync={DisposeRootAsync}\n"
        + string.Join("\n", Registrations.Select(r => "  " + r)) + "\n"
        + string.Join("\n", Ops.Select(o => "  " + o));
}

/// <summary>Runs a scenario against a container and writes down everything observable, one line per step.</summary>
public static class ScenarioRunner
{
    public static string Run(Scenario scenario, Func<IServiceCollection, Scenario, IServiceProvider> build)
    {
        var log = new RunLog();
        var lines = new List<string>();
        var describer = new Describer();
        IServiceProvider root;
        try
        {
            root = build(Materialize(scenario, log), scenario);
        }
#pragma warning disable CA1031 // every exception is an observation to compare
        catch (Exception e)
        {
            return "build " + Describer.Exception(e);
        }

        // Index 0 is the container itself; scopes are appended as the script creates them.
        var scopes = new List<(IServiceProvider Provider, object Handle)> { (root, root) };
        foreach (Op op in scenario.Ops)
        {
            try
            {
                lines.Add(Execute(op, scopes, describer));
            }
            catch (Exception e)
            {
                lines.Add($"{op.Kind} {Describer.Exception(e)}");
            }
        }

        try
        {
            Dispose(root, scenario.DisposeRootAsync);
            lines.Add("root disposed");
        }
        catch (Exception e)
        {
            lines.Add("root dispose " + Describer.Exception(e));
        }
#pragma warning restore CA1031

        lines.Add("disposals " + string.Join(",", log.Disposals));
        return string.Join("\n", lines);
    }

    private static string Execute(Op op, List<(IServiceProvider Provider, object Handle)> scopes, Describer describer)
    {
        int index = op.Scope % scopes.Count;
        IServiceProvider provider = scopes[index].Provider;
        Type service = typeof(IS<>).MakeGenericType(Scenario.Markers[op.Service % Scenario.Services]);
        object? key = Scenario.Keys[op.Key % Scenario.Keys.Length];
        switch (op.Kind)
        {
            case OpKind.Get:
                return $"get {Describer.Name(service)} in {index}: {describer.Describe(provider.GetService(service))}";
            case OpKind.GetKeyed:
                return $"get {Describer.Name(service)} [{Describer.Key(key)}] in {index}: {describer.Describe(provider.GetKeyedService(service, key))}";
            case OpKind.GetAll:
                return $"all {Describer.Name(service)} in {index}: {describer.Describe(provider.GetServices(service))}";
            case OpKind.GetAllKeyed:
                return $"all {Describer.Name(service)} [{Describer.Key(key)}] in {index}: {describer.Describe(provider.GetKeyedServices(service, key))}";
            case OpKind.GetRequired:
                return $"required {Describer.Name(service)} in {index}: {describer.Describe(provider.GetRequiredService(service))}";
            case OpKind.CreateScope:
                IServiceScope scope = provider.GetRequiredService<IServiceScopeFactory>().CreateScope();
                scopes.Add((scope.ServiceProvider, scope));
                describer.Label(scope.ServiceProvider, $"scope{scopes.Count - 1}");
                return $"scope {scopes.Count - 1} from {index}";
            default:
                // Only scopes: the container is disposed once, at the end, so most scripts keep resolving after a
                // scope is gone (use-after-dispose is still exercised through the disposed scopes).
                if (scopes.Count == 1)
                {
                    return "no scope to dispose";
                }

                int target = 1 + (op.Scope % (scopes.Count - 1));
                Dispose(scopes[target].Handle, op.Kind == OpKind.DisposeAsync);
                return $"disposed {target}";
        }
    }

    private static void Dispose(object handle, bool async)
    {
        if (async && handle is IAsyncDisposable asyncDisposable)
        {
            asyncDisposable.DisposeAsync().AsTask().GetAwaiter().GetResult();
        }
        else
        {
            ((IDisposable)handle).Dispose();
        }
    }

    private static IServiceCollection Materialize(Scenario scenario, RunLog log)
    {
        IServiceCollection services = new ServiceCollection();
        services.AddSingleton(log);
        foreach (Registration r in scenario.Registrations)
        {
            services.Add(Descriptor(r, scenario.Acyclic, log));
        }

        return services;
    }

    private static ServiceDescriptor Descriptor(Registration r, bool acyclic, RunLog log)
    {
        int self = r.Service % Scenario.Services;
        Type marker = Scenario.Markers[self];
        Type service = typeof(IS<>).MakeGenericType(marker);
        object? key = Scenario.Keys[r.Key % 4];
        Type a = Dependency(r.DepA, self, acyclic);
        Type b = Dependency(r.DepB, self, acyclic);

        switch (r.Template)
        {
            case Template.Instance:
                object instance = Activator.CreateInstance(typeof(Leaf<>).MakeGenericType(marker), log)!;
                return key is null ? new ServiceDescriptor(service, instance) : new ServiceDescriptor(service, key, instance);
            case Template.Factory when key is null:
                Type unkeyedProduct = typeof(Dep1<,>).MakeGenericType(marker, typeof(object));
                return new ServiceDescriptor(service, sp => Activator.CreateInstance(unkeyedProduct, log, acyclic ? sp.GetService(a) : null)!, r.Lifetime);
            case Template.Factory:
                Type keyedProduct = typeof(Dep2<,,>).MakeGenericType(marker, typeof(object), typeof(object));
                return new ServiceDescriptor(service, key, (sp, k) => Activator.CreateInstance(keyedProduct, log, k, acyclic ? sp.GetService(a) : null)!, r.Lifetime);
            case Template.Open or Template.OpenDisposable or Template.OpenConstrained:
                Type open = r.Template switch
                {
                    Template.Open => typeof(Open<>),
                    Template.OpenDisposable => typeof(OpenDisposable<>),
                    _ => typeof(OpenConstrained<>),
                };
                return new ServiceDescriptor(typeof(IS<>), key, open, r.Lifetime);
            default:
                Type implementation = r.Template switch
                {
                    Template.Leaf => typeof(Leaf<>).MakeGenericType(marker),
                    Template.Dep1 => typeof(Dep1<,>).MakeGenericType(marker, a),
                    Template.Dep2 => typeof(Dep2<,,>).MakeGenericType(marker, a, b),
                    Template.Many => typeof(Many<,>).MakeGenericType(marker, ItemOf(a)),
                    Template.WithProvider => typeof(WithProvider<>).MakeGenericType(marker),
                    Template.Disposable => typeof(Disposable<,>).MakeGenericType(marker, a),
                    Template.AsyncDisposable => typeof(AsyncDisposable<,>).MakeGenericType(marker, a),
                    Template.BothDisposable => typeof(BothDisposable<,>).MakeGenericType(marker, a),
                    Template.Longest => typeof(Longest<,,>).MakeGenericType(marker, a, b),
                    Template.Either => typeof(Either<,,>).MakeGenericType(marker, a, b),
                    Template.KeyedDep => typeof(KeyedDep<,>).MakeGenericType(marker, a),
                    Template.InheritedKeyDep => typeof(InheritedKeyDep<,>).MakeGenericType(marker, a),
                    Template.KeyAware => typeof(KeyAware<>).MakeGenericType(marker),
                    Template.IntKeyAware => typeof(IntKeyAware<>).MakeGenericType(marker),
                    Template.Optional => typeof(Optional<,>).MakeGenericType(marker, a),
                    _ => typeof(Throws<,>).MakeGenericType(marker, a),
                };
                return key is null ? new ServiceDescriptor(service, implementation, r.Lifetime) : new ServiceDescriptor(service, key, implementation, r.Lifetime);
        }
    }

    private static Type Dependency(int raw, int self, bool acyclic)
    {
        raw %= 2 * Scenario.Services + 1;
        if (raw == 2 * Scenario.Services || (acyclic && self == 0))
        {
            return typeof(RunLog);
        }

        int target = raw % Scenario.Services;
        if (acyclic)
        {
            target %= self; // strictly lower-numbered: no path can come back
        }

        Type dependency = typeof(IS<>).MakeGenericType(Scenario.Markers[target]);
        return raw >= Scenario.Services ? typeof(IEnumerable<>).MakeGenericType(dependency) : dependency;
    }

    private static Type ItemOf(Type dependency) =>
        dependency.IsGenericType && dependency.GetGenericTypeDefinition() == typeof(IEnumerable<>) ? dependency.GenericTypeArguments[0] : dependency;
}

/// <summary>
/// Writes an object graph in a container-independent form. A node prints in full the first time it is seen and as
/// <c>#id</c> afterwards, ids being creation order, so equal strings mean the same instances were shared, in the same
/// places, created in the same order. Providers are named by first appearance (or by the scope that owns them).
/// </summary>
public sealed partial class Describer
{
    private readonly HashSet<Node> _seen = new(ReferenceEqualityComparer.Instance);
    private readonly Dictionary<object, string> _providers = new(ReferenceEqualityComparer.Instance);

    public void Label(IServiceProvider provider, string label) => _providers.TryAdd(provider, label);

    public string Describe(object? value)
    {
        switch (value)
        {
            case null:
                return "null";
            case Node node when !_seen.Add(node):
                return $"#{node.Id}";
            case Node node:
                return $"{Name(node.GetType())}#{node.Id}({string.Join(",", node.Parts.Select(Describe))})";
            case IServiceProvider provider:
                if (!_providers.TryGetValue(provider, out string? label))
                {
                    _providers[provider] = label = $"sp{_providers.Count}";
                }

                return label;
            case string text:
                return $"'{text}'";
            case IEnumerable items:
                return "[" + string.Join(",", items.Cast<object?>().Select(Describe)) + "]";
            default:
                return Key(value);
        }
    }

    /// <summary>The observations without exception messages, which is what the containers must agree on.</summary>
    public static string Comparable(string observations) => MessagePattern().Replace(observations, "");

    [System.Text.RegularExpressions.GeneratedRegex(@" \{[^{}]*\}")]
    private static partial System.Text.RegularExpressions.Regex MessagePattern();

    public static string Key(object? key) => key is null ? "null" : ReferenceEquals(key, KeyedService.AnyKey) ? "AnyKey" : key.ToString()!;

    /// <summary>
    /// The exception's type, plus for InvalidOperationException which rule it reports (taken from the message, whose
    /// wording both containers share), so "refused a cycle" and "refused an ambiguous constructor" don't compare equal.
    /// ValidateOnBuild's per-descriptor wrapper is shown with what it wraps.
    /// </summary>
    public static string Exception(Exception e)
    {
        var text = new StringBuilder("!").Append(e.GetType().Name);
        if (e is AggregateException aggregate)
        {
            return text.Append('(').AppendJoin(",", aggregate.InnerExceptions.Select(Exception)).Append(')').ToString();
        }

        bool plain = e.GetType() == typeof(InvalidOperationException);
        if (plain && e.InnerException is { } wrapped && e.Message.StartsWith("Error while validating", StringComparison.Ordinal))
        {
            return text.Append('<').Append(Exception(wrapped)).Append('>').ToString();
        }

        if (plain)
        {
            text.Append(':').Append(Kind(e.Message));
        }

        // Carried for diagnosing a divergence, but stripped before comparing (see Comparable): wording isn't claimed.
        return text.Append(" {").Append(e.Message.Replace('{', '(').Replace('}', ')')).Append('}').ToString();
    }

    private static string Kind(string message) => message switch
    {
        _ when message.StartsWith("A circular dependency", StringComparison.Ordinal) => "cycle",
        _ when message.Contains("constructors are ambiguous", StringComparison.Ordinal) => "ambiguous",
        _ when message.StartsWith("Cannot consume", StringComparison.Ordinal) => "captive",
        _ when message.Contains("from root provider", StringComparison.Ordinal) => "scoped-from-root",
        _ when message.StartsWith("Unable to resolve service", StringComparison.Ordinal) => "unresolvable",
        _ when message.StartsWith("No constructor for type", StringComparison.Ordinal) => "no-satisfiable-constructor",
        _ when message.StartsWith("KeyedService.AnyKey", StringComparison.Ordinal) => "anykey",
        _ when message.StartsWith("No service for type", StringComparison.Ordinal) || message.StartsWith("No keyed service", StringComparison.Ordinal) => "missing",
        _ when message.Contains("only implements IAsyncDisposable", StringComparison.Ordinal) => "async-only",
        _ when message.StartsWith("The type of the key", StringComparison.Ordinal) => "key-type",
        _ => "other: " + message,
    };

    public static string Name(Type type)
    {
        if (!type.IsGenericType)
        {
            return type.Name;
        }

        string name = type.Name[..type.Name.IndexOf('`', StringComparison.Ordinal)];
        return $"{name}<{string.Join(",", type.GenericTypeArguments.Select(Name))}>";
    }
}

using Ladder.DI.Tests.Graph;
using Microsoft.Extensions.DependencyInjection;

namespace Ladder.DI.Tests;

/// <summary>
/// Tests written for the mutants that survived both the unit tests and the specification suite (05-di/evidence/stryker.md).
/// Wherever Microsoft's container has a defined answer, the test asks both containers and requires the same exception
/// type and message, since our messages copy Microsoft's on purpose.
/// </summary>
public class MutationGapTests
{
    private static ServiceContainer Ours(IServiceCollection services, bool validateScopes = false, bool validateOnBuild = false) =>
        services.BuildLadderServiceProvider(new ServiceContainerOptions { ValidateScopes = validateScopes, ValidateOnBuild = validateOnBuild });

    private static ServiceProvider Microsoft(IServiceCollection services, bool validateScopes = false, bool validateOnBuild = false) =>
        services.BuildServiceProvider(new ServiceProviderOptions { ValidateScopes = validateScopes, ValidateOnBuild = validateOnBuild });

    private static (Type Type, string Message) Failure(Action action)
    {
        Exception e = Assert.ThrowsAny<Exception>(action);
        return (e.GetType(), e.Message);
    }

    private static void SameFailure(Func<IServiceCollection> services, Action<IServiceProvider> act, bool validateScopes = false)
    {
        (Type Type, string Message) expected = Failure(() => act(Microsoft(services(), validateScopes)));
        (Type Type, string Message) actual = Failure(() => act(Ours(services(), validateScopes)));
        Assert.Equal(expected, actual);
    }

    // --- Registration errors, seen when the container is built (Planner.Validate) ---------------------------------

    public static TheoryData<string> BadRegistrations => ["open service, closed implementation", "open service, abstract open implementation",
        "open service, interface implementation", "arity mismatch", "closed service, abstract implementation", "closed service, open implementation",
        "open service, factory"];

    private static ServiceCollection BadRegistration(string name)
    {
        var services = new ServiceCollection();
        ((ICollection<ServiceDescriptor>)services).Add(name switch
        {
            "open service, closed implementation" => new ServiceDescriptor(typeof(IOpen<>), typeof(Closed), ServiceLifetime.Transient),
            "open service, abstract open implementation" => new ServiceDescriptor(typeof(IOpen<>), typeof(AbstractOpen<>), ServiceLifetime.Transient),
            "open service, interface implementation" => new ServiceDescriptor(typeof(IOpen<>), typeof(IOpen<>), ServiceLifetime.Transient),
            "arity mismatch" => new ServiceDescriptor(typeof(IOpen<>), typeof(TwoArgs<,>), ServiceLifetime.Transient),
            "closed service, abstract implementation" => new ServiceDescriptor(typeof(IClosed), typeof(AbstractClosed), ServiceLifetime.Transient),
            "closed service, open implementation" => new ServiceDescriptor(typeof(IClosed), typeof(Open<>), ServiceLifetime.Transient),
            _ => new ServiceDescriptor(typeof(IOpen<>), _ => new Closed(), ServiceLifetime.Transient),
        });
        return services;
    }

    [Theory]
    [MemberData(nameof(BadRegistrations))]
    public void A_bad_registration_fails_at_build_exactly_as_Microsofts_does(string name)
    {
        (Type Type, string Message) expected = Failure(() => Microsoft(BadRegistration(name)));
        (Type Type, string Message) actual = Failure(() => Ours(BadRegistration(name)));
        Assert.Equal(expected, actual);
    }

    [Fact]
    public void Null_arguments_are_rejected_with_ArgumentNullException()
    {
        Assert.Throws<ArgumentNullException>(() => new ServiceContainer(null!));
        Assert.Throws<ArgumentNullException>(() => new ServiceContainer(new ServiceCollection(), null!));
        var isService = Ours(new ServiceCollection()).GetRequiredService<IServiceProviderIsService>();
        Assert.Throws<ArgumentNullException>(() => isService.IsService(null!));
    }

    // --- IServiceProviderIsService and IServiceProviderIsKeyedService ---------------------------------------------

    [Fact]
    public void The_IsService_built_ins_are_resolvable_and_report_themselves()
    {
        foreach (IServiceProvider provider in new IServiceProvider[] { Microsoft(new ServiceCollection()), Ours(new ServiceCollection()) })
        {
            var isService = provider.GetRequiredService<IServiceProviderIsService>();
            var isKeyed = provider.GetRequiredService<IServiceProviderIsKeyedService>();
            Assert.True(isService.IsService(typeof(IServiceProviderIsService)));
            Assert.True(isService.IsService(typeof(IServiceProviderIsKeyedService)));
            Assert.True(isService.IsService(typeof(IServiceProvider)));
            Assert.True(isService.IsService(typeof(IServiceScopeFactory)));
            Assert.False(isService.IsService(typeof(IClosed)));
            Assert.True(isKeyed.IsKeyedService(typeof(IServiceProviderIsService), null));
        }
    }

    public static TheoryData<string> IsServiceQueries => ["unkeyed, only AnyKey registered", "keyed, only AnyKey registered", "keyed, other key registered",
        "open definition", "closed generic of registered open", "IEnumerable of unregistered"];

    [Theory]
    [MemberData(nameof(IsServiceQueries))]
    public void IsService_answers_like_Microsofts(string query)
    {
        static ServiceCollection Services()
        {
            var services = new ServiceCollection();
            services.AddKeyedTransient<IClosed, ClosedService>(KeyedService.AnyKey);
            services.AddKeyedTransient<IOther, OtherService>("a");
            services.AddTransient(typeof(IOpen<>), typeof(Open<>));
            return services;
        }

        bool Ask(IServiceProvider provider)
        {
            var isKeyed = provider.GetRequiredService<IServiceProviderIsKeyedService>();
            return query switch
            {
                "unkeyed, only AnyKey registered" => isKeyed.IsService(typeof(IClosed)),
                "keyed, only AnyKey registered" => isKeyed.IsKeyedService(typeof(IClosed), "x"),
                "keyed, other key registered" => isKeyed.IsKeyedService(typeof(IOther), "b"),
                "open definition" => isKeyed.IsService(typeof(IOpen<>)),
                "closed generic of registered open" => isKeyed.IsService(typeof(IOpen<int>)),
                _ => isKeyed.IsService(typeof(IEnumerable<IOther>)),
            };
        }

        Assert.Equal(Ask(Microsoft(Services())), Ask(Ours(Services())));
    }

    // --- Error messages and the type names inside them ------------------------------------------------------------

    [Fact]
    public void A_type_without_a_public_constructor_fails_like_Microsofts()
    {
        SameFailure(() => new ServiceCollection().AddTransient<NoPublicConstructor>(), p => p.GetService<NoPublicConstructor>());
    }

    [Fact]
    public void A_missing_required_service_fails_like_Microsofts()
    {
        SameFailure(() => new ServiceCollection(), p => p.GetRequiredService<IClosed>());
        SameFailure(() => new ServiceCollection(), p => p.GetRequiredKeyedService<IClosed>("k"));
    }

    [Fact]
    public void Resolving_scoped_services_from_the_root_fails_like_Microsofts()
    {
        static IServiceCollection Services() => new ServiceCollection().AddScoped<IClosed, ClosedService>().AddTransient<NeedsClosed>();
        SameFailure(Services, p => p.GetService<IClosed>(), validateScopes: true);      // directly
        SameFailure(Services, p => p.GetService<NeedsClosed>(), validateScopes: true);  // through a dependency
    }

    [Fact]
    public void ValidateOnBuild_aggregates_like_Microsofts()
    {
        static IServiceCollection Services() => new ServiceCollection().AddSingleton<NeedsClosed>();
        (Type Type, string Message) expected = Failure(() => Microsoft(Services(), validateOnBuild: true));
        (Type Type, string Message) actual = Failure(() => Ours(Services(), validateOnBuild: true));
        Assert.Equal(expected, actual);
    }

    public static TheoryData<string> CycleShapes => ["keywords", "arrays", "nested generic"];

    [Theory]
    [MemberData(nameof(CycleShapes))]
    public void A_circular_dependency_message_names_types_like_Microsofts(string shape)
    {
        // The cycle runs through a generic service whose type arguments exercise TypeNames: C# keywords, arrays of
        // several ranks, and a generic type nested in a generic type.
        Type through = shape switch
        {
            "keywords" => typeof(IThrough<(bool, byte, char, decimal, double, float, int, long, object, sbyte, short, string, uint, ulong, ushort)>),
            "arrays" => typeof(IThrough<int[][,]>),
            _ => typeof(IThrough<Outer<int>.Inner<string>>),
        };
        IServiceCollection Services() => new ServiceCollection()
            .AddTransient(typeof(IThrough<>), typeof(Through<>))
            .AddTransient(typeof(Back<>), typeof(Back<>))
            .AddTransient(typeof(IOpen<>), typeof(OpenNeedingThrough<>));
        Type start = through.GetGenericArguments()[0];
        SameFailure(Services, p => p.GetService(typeof(IThrough<>).MakeGenericType(start)));
    }

    // --- Scope slot growth (Scope.GetOrCreateScoped) --------------------------------------------------------------

    [Theory]
    [InlineData(ResolutionMode.Compiled)]
    [InlineData(ResolutionMode.Interpreted)]
    public void Scoped_services_first_planned_after_a_scope_exists_keep_one_instance_per_scope(ResolutionMode mode)
    {
        var services = new ServiceCollection();
        Type[] types = [typeof(Slot<K0>), typeof(Slot<K1>), typeof(Slot<K2>), typeof(Slot<K3>), typeof(Slot<K4>), typeof(Slot<K5>),
            typeof(Slot<Slot<K0>>), typeof(Slot<Slot<K1>>), typeof(Slot<Slot<K2>>), typeof(Slot<Slot<K3>>), typeof(Slot<Slot<K4>>)];
        foreach (Type t in types)
        {
            services.AddScoped(t);
        }

        using ServiceContainer container = services.BuildLadderServiceProvider(new ServiceContainerOptions { Mode = mode });
        using IServiceScope scope = container.CreateScope(); // created before any scoped plan exists, so its slot array starts empty
        using IServiceScope other = container.CreateScope();

        // Resolve in reverse so later slots are claimed before earlier ones are written.
        object[] first = [.. types.Reverse().Select(t => scope.ServiceProvider.GetRequiredService(t))];
        object[] again = [.. types.Reverse().Select(t => scope.ServiceProvider.GetRequiredService(t))];
        object[] elsewhere = [.. types.Reverse().Select(t => other.ServiceProvider.GetRequiredService(t))];
        for (int i = 0; i < types.Length; i++)
        {
            Assert.Same(first[i], again[i]);
            Assert.NotSame(first[i], elsewhere[i]);
        }
    }

    // --- ServiceId equality ---------------------------------------------------------------------------------------

    [Fact]
    public void ServiceId_equality_needs_both_type_and_key_to_match()
    {
        Assert.NotEqual(new ServiceId(null, typeof(IClosed)), new ServiceId(null, typeof(IOther)));
        Assert.NotEqual(new ServiceId("a", typeof(IClosed)), new ServiceId("b", typeof(IClosed)));
        Assert.NotEqual(new ServiceId("a", typeof(IClosed)), new ServiceId(null, typeof(IClosed)));
        Assert.NotEqual(new ServiceId(null, typeof(IClosed)), new ServiceId("a", typeof(IClosed)));
        Assert.Equal(new ServiceId("a", typeof(IClosed)), new ServiceId(new string('a', 1), typeof(IClosed)));
        Assert.Equal(new ServiceId("a", typeof(IClosed)).GetHashCode(), new ServiceId(new string('a', 1), typeof(IClosed)).GetHashCode());
        Assert.Equal("Ladder.DI.Tests.MutationGapTests+IClosed", new ServiceId(null, typeof(IClosed)).ToString());
        Assert.Equal("(a, Ladder.DI.Tests.MutationGapTests+IClosed)", new ServiceId("a", typeof(IClosed)).ToString());
    }

    // --- Second round: survivors of the first round (see 05-di/evidence/stryker.md) -------------------------------

    [Fact]
    public void A_missing_required_service_asked_for_with_a_null_key_fails_like_Microsofts()
    {
        SameFailure(() => new ServiceCollection(), p => p.GetRequiredKeyedService<IClosed>(null));
    }

    [Theory]
    [InlineData(ResolutionMode.Compiled)]
    [InlineData(ResolutionMode.Interpreted)]
    public void A_disposable_transient_made_by_a_factory_is_disposed_with_its_scope(ResolutionMode mode)
    {
        var services = new ServiceCollection().AddTransient(_ => new Tracker());
        using ServiceContainer container = services.BuildLadderServiceProvider(new ServiceContainerOptions { Mode = mode });
        var made = new List<Tracker>();
        using (IServiceScope scope = container.CreateScope())
        {
            for (int i = 0; i < 3; i++) // three calls, so the compiled engine is reached on the second
            {
                made.Add(scope.ServiceProvider.GetRequiredService<Tracker>());
            }
        }

        Assert.All(made, t => Assert.True(t.Disposed));
    }

    [Fact]
    public void An_open_generic_IEnumerable_registration_is_used_like_Microsofts()
    {
        static IServiceCollection Services() => new ServiceCollection()
            .AddTransient<IClosed, ClosedService>()
            .AddTransient(typeof(IEnumerable<>), typeof(CustomEnumerable<>));
        Assert.Equal(Microsoft(Services()).GetService<IEnumerable<IClosed>>()?.GetType(), Ours(Services()).GetService<IEnumerable<IClosed>>()?.GetType());
    }

    [Fact]
    public void Keyed_enumerations_share_instances_with_single_resolutions_like_Microsofts()
    {
        // Singletons under a specific key, under another key, and under AnyKey. Which enumerated instances are the
        // same objects as single resolutions depends on the slot each registration gets; the pattern must match.
        static IServiceCollection Services() => new ServiceCollection()
            .AddKeyedSingleton<IClosed, ClosedService>("a")
            .AddKeyedSingleton<IClosed, ClosedService>("a")
            .AddKeyedSingleton<IClosed, ClosedService>("b")
            .AddKeyedSingleton<IClosed, ClosedService>(KeyedService.AnyKey);

        static bool[] Pattern(IServiceProvider p)
        {
            object[] any = [.. p.GetKeyedServices<IClosed>(KeyedService.AnyKey)];
            object[] a = [.. p.GetKeyedServices<IClosed>("a")];
            object[] x = [.. p.GetKeyedServices<IClosed>("x")];
            object[] singles = [p.GetRequiredKeyedService<IClosed>("a"), p.GetRequiredKeyedService<IClosed>("b"), p.GetRequiredKeyedService<IClosed>("x")];
            object[] all = [.. any, .. a, .. x, .. singles];
            return [.. from i in all from j in all select ReferenceEquals(i, j), .. new[] { any.Length == 3, a.Length == 2, x.Length == 1 }];
        }

        Assert.Equal(Pattern(Microsoft(Services())), Pattern(Ours(Services())));
    }

    [Fact]
    public void Default_parameter_values_are_supplied_like_Microsofts()
    {
        static string Describe(IServiceProvider p)
        {
            var d = p.GetRequiredService<WithDefaults>();
            return $"{d.Point.X},{d.Point.Y}|{d.Mode}|{d.Count}|{d.Name ?? "null"}";
        }

        static IServiceCollection Services() => new ServiceCollection().AddTransient<WithDefaults>();
        Assert.Equal(Describe(Microsoft(Services())), Describe(Ours(Services())));
    }

    [Fact]
    public void A_ServiceKey_parameter_under_AnyKey_gets_the_key_like_Microsofts()
    {
        static IServiceCollection Services() => new ServiceCollection().AddKeyedTransient<KeyTaker>(KeyedService.AnyKey);
        static string Describe(IServiceProvider p) =>
            string.Join(",", p.GetKeyedServices<KeyTaker>(KeyedService.AnyKey).Select(k => k.Key?.ToString() ?? "null"))
            + "|" + (p.GetKeyedService<KeyTaker>("z")?.Key?.ToString() ?? "null");
        Assert.Equal(Describe(Microsoft(Services())), Describe(Ours(Services())));
    }

    [Fact]
    public void Keyed_resolution_after_the_container_is_disposed_fails_like_Microsofts()
    {
        static IServiceCollection Services() => new ServiceCollection().AddKeyedTransient<IClosed, ClosedService>("k");
        SameFailure(Services, p =>
        {
            ((IDisposable)p).Dispose();
            p.GetKeyedService<IClosed>("k");
        });
    }

    public sealed class Tracker : IDisposable
    {
        public bool Disposed { get; private set; }

        public void Dispose() => Disposed = true;
    }

    public sealed class CustomEnumerable<T> : List<T>;

    public readonly record struct Point(int X, int Y);

    public enum Mode
    {
        First,
        Second,
    }

    public sealed class WithDefaults(Point point = default, Mode? mode = Mode.Second, int count = 7, string? name = null)
    {
        public Point Point { get; } = point;

        public Mode? Mode { get; } = mode;

        public int Count { get; } = count;

        public string? Name { get; } = name;
    }

    public sealed class KeyTaker([ServiceKey] object? key)
    {
        public object? Key { get; } = key;
    }

    public interface IOpen<T>;

    public interface IClosed;

    public interface IOther;

    public interface IThrough<T>;

    public sealed class Closed;

    public sealed class ClosedService : IClosed;

    public sealed class OtherService : IOther;

    public abstract class AbstractOpen<T> : IOpen<T>;

    public sealed class TwoArgs<T, U> : IOpen<T>;

    public abstract class AbstractClosed : IClosed;

    public sealed class Open<T> : IOpen<T>, IClosed;

    public sealed class NeedsClosed(IClosed closed)
    {
        public IClosed Closed { get; } = closed;
    }

    public sealed class NoPublicConstructor
    {
        private NoPublicConstructor()
        {
        }
    }

    public sealed class Through<T>(Back<T> back) : IThrough<T>
    {
        public Back<T> Back { get; } = back;
    }

    public sealed class Back<T>(IOpen<T> open)
    {
        public IOpen<T> Open { get; } = open;
    }

    public sealed class OpenNeedingThrough<T>(IThrough<T> through) : IOpen<T>
    {
        public IThrough<T> Through { get; } = through;
    }

    public sealed class Slot<T>;

    public sealed class Outer<T>
    {
        public sealed class Inner<U>;
    }
}
